            id = 667, name = "Death From Below", name_fr = "La mort venue d'en-bas", level = 44, requiredLevel = 35, special = true,
            objective = "Protect Shakes O'Breen during the attack.", objective_fr = "Protéger Shakes O'Breen lors de l'attaque.",
            start = { kind = "npc", id = 2610, name = "Shakes O'Breen", name_fr = "Shakes O'Breen", areaID = 45, uiMapID = 1417, x = 32.28, y = 81.38 },
            prerequisitesAny = { { id = 670, name = "Sunken Treasure", name_fr = "Le trésor englouti" } },
        },
        [6622] = {
            id = 6622, name = "Triage", name_fr = "Triage", level = 45, requiredLevel = 35, raceMask = 8589934770, special = true,
            objective = "Save patients by using Triage Bandages to tend to their wounds. You must save 15 patients before 6 of them die from their injuries.  Remember the order of triage! Critically Injured Soldiers die the fastest followed by Badly Injured Soldiers. Injured Soldiers take the longest to die and should be saved AFTER your Critically Injured and Badly Injured Soldiers have been triaged.", objective_fr = "Sauver des patients en utilisant des Bandages de Triage, afin de panser leurs blessures. Vous devez sauver 15 patients avant que 6 d’entre eux ne meurent de leurs blessures.  Rappelez-vous l’ordre du triage ! Les Soldats agonisants meurent les premiers, suivis des Soldats grièvement blessés. Les Soldats blessés sont ceux qui meurent les derniers, et ils doivent être soignés APRES ceux qui agonisent et ceux qui sont grièvement blessés ; selon le tri que vous avez fait.",
            start = { kind = "npc", id = 12920, name = "Doctor Gregory Victor", name_fr = "Docteur Gregory Victor", areaID = 45, uiMapID = 1417, x = 73.41, y = 36.89 },
        },
        [656] = {
            id = 656, name = "Summoning the Princess", name_fr = "L'invocation de la Princesse", level = 50, requiredLevel = 30,
            objective = "Go to the Shards of Myzrael, summon her and defeat her.  Gather her Eldritch Shackles and bind them to the Shards of Myzrael.", objective_fr = "Aller aux Eclats de Myzrael, l'invoquer et la battre.  Prendre ses Chaînes indicibles et les attacher aux Eclats de Myzrael.",
            start = { kind = "npc", id = 2785, name = "Theldurin the Lost", name_fr = "Theldurin l’Egaré", areaID = 3, uiMapID = 1418, x = 51.39, y = 76.87 },
            prerequisitesAny = { { id = 692, name = "The Lost Fragments", name_fr = "Les fragments perdus" } },
        },
        [5146] = {
            id = 5146, name = "Elemental Leatherworking", name_fr = "Travail du cuir élémentaire", level = 55, requiredLevel = 40, raceMask = 8589934770,
            objective = "Bring 2 Heart of Fire, 2 Globe of Water, 2 Core of Earth, and 2 Breath of Wind to Brumn Winterhoof in the Arathi Mountains.  Completing this quest will give you access to the Elemental Leatherworking arts.  The completion of this quest will prevent you from learning Dragonscale Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so.", objective_fr = "Apporter 2 Coeurs de feu, 2 Globes d'eau, 2 Noyaux de terre, et 2 Souffles de vent à Brumn Winterhoof dans les montagnes d’Arathi.  L’accomplissement de cette quête donne accès aux arts du travail du cuir élémentaire.  L’accomplissement de cette quête vous empêchera d’apprendre le travail du cuir de dragon et le travail du cuir tribal ; il faut être sûr du chemin que l’on veut suivre avant de faire ce choix.",
            start = { kind = "npc", id = 7869, name = "Brumn Winterhoof", name_fr = "Brumn Winterhoof", areaID = 45, uiMapID = 1417, x = 28.27, y = 45.09 },
        },
    },
}
