        [2339] = {
            id = 2339, name = "Find the Gems and Power Source", name_fr = "Trouver les Gemmes et la Source d'énergie", level = 44, requiredLevel = 37, raceMask = 8589934770,
            objective = "Recover all three gems and a power source for the necklace from Uldaman, and then bring them to Jarkal Mossmeld in Kargath. Jarkal believes a power source might be found on the strongest construct present in Uldaman.  From the journal, you know... * The ruby has been stashed in a barricaded Shadowforge area. * The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves. * The sapphire has been claimed by Grimlok, the trogg leader.", objective_fr = "Récupérer, dans Uldaman, les trois gemmes et une source d’énergie pour le collier, puis les rapporter à Jarkal Mossmeld, à Kargath. Jarkal pense que vous pouvez trouver une source d’énergie sur la machine la plus puissante d’Uldaman.  C'est dans le journal, vous savez...  * Le rubis a été caché dans une zone barricadée des Ombreforge. * La topaze a été dissimulée dans une urne, dans l’une des zones trogg, pas très loin de nains de Alliance. * Le saphir est possession du chef trogg, Grimlok.",
            start = { kind = "npc", id = 6868, name = "Jarkal Mossmeld", name_fr = "Jarkal Mossmeld", areaID = 3, uiMapID = 1418, x = 2.42, y = 46.06 },
            prerequisitesAny = { { id = 2338, name = "Translating the Journal", name_fr = "La Traduction du Journal" } },
        },
