            prerequisitesAny = { { id = 732, name = "Tremors of the Earth", name_fr = "Tremblement de terre" } },
        },
        [3981] = {
            id = 3981, name = "Commander Gor'shak", name_fr = "Le commandant Gor'shak", level = 52, requiredLevel = 48, raceMask = 8589934770,
            objective = "Find Commander Gor'shak in Blackrock Depths.  You recall that the crudely drawn picture of the orc included bars drawn over the portrait. Perhaps you should search for a prison of some sort.", objective_fr = "Trouver le commandant Gor'shak dans les Profondeurs de Blackrock.  Le dessin grossier représentait également des barreaux. Peut-être devriez-vous rechercher un genre de prison.",
            start = { kind = "npc", id = 9081, name = "Galamav the Marksman", name_fr = "Galamav le Tireur d'élite", areaID = 3, uiMapID = 1418, x = 5.96, y = 47.73 },
