            objective = "Venture forth to the Burning Steppes and find out what became of Sha'ni Proudtusk.", objective_fr = "S'aventurer dans les Steppes ardentes et découvrir ce qu'il est advenu de Sha'ni Proudtusk.",
            start = { kind = "npc", id = 9082, name = "Thal'trak Proudtusk", name_fr = "Thal'trak Proudtusk", areaID = 3, uiMapID = 1418, x = 3.36, y = 48.06 },
            nextQuest = { id = 3822, name = "Krom'Grul", name_fr = "Krom'Grul" },
