        [4081] = {
            id = 4081, name = "KILL ON SIGHT: Dark Iron Dwarves", name_fr = "TUER A VUE : nains Sombrefer", level = 52, requiredLevel = 48, raceMask = 8589934770,
            objective = "Venture to Blackrock Depths and destroy the vile aggressors!  Warlord Goretooth wants you to kill 15 Anvilrage Guardsmen, 10 Anvilrage Wardens and 5 Anvilrage Footmen. Return to him once your task is complete.  ", objective_fr = "Pénétrer dans les Profondeurs de Blackrock et tuer les vils agresseurs !  Le chef de guerre Goretooth veut que vous tuiez 15 Gardes Ragenclumes, 10 Gardiens Ragenclumes et 5 Fantassins Ragenclumes. Retourner le voir une fois votre mission accomplie.",
            start = { kind = "object", id = 164867, name = "WANTED", name_fr = "RECHERCHE", areaID = 3, uiMapID = 1418, x = 3.74, y = 47.43 },
        },
        [4082] = {
            id = 4082, name = "KILL ON SIGHT: High Ranking Dark Iron Officials", name_fr = "TUER A VUE : Officiers de haut rang Sombrefer", level = 54, requiredLevel = 50, raceMask = 8589934770,
            objective = "Venture to Blackrock Depths and destroy the vile aggressors!  Warlord Goretooth wants you to kill 10 Anvilrage Medics, 10 Anvilrage Soldiers and 10 Anvilrage Officers. Return to him once your task is complete.", objective_fr = "Pénétrer dans les Profondeurs de Blackrock et tuer les vils agresseurs !  Le Chef de guerre Goretooth veut que vous tuiez 10 Médecins Ragenclumes, 10 Soldats Ragenclumes et 10 Officiers Ragenclumes. Retourner le voir une fois votre mission accomplie.",
            start = { kind = "object", id = 164868, name = "KILL ON SIGHT", name_fr = "TUER A VUE", areaID = 3, uiMapID = 1418, x = 3.94, y = 46.73 },
            prerequisitesAny = { { id = 4081, name = "KILL ON SIGHT: Dark Iron Dwarves", name_fr = "TUER A VUE : nains Sombrefer" } },
        },
        [7201] = {
            id = 7201, name = "The Last Element", name_fr = "Le dernier élément", level = 54, requiredLevel = 48, raceMask = 8589934770,
            objective = "Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals. ", objective_fr = "Partir pour les Profondeurs de Blackrock et trouver 10 Essences des éléments. Commencer vos recherches par les golems et par les créateurs de golems. Vivian Lagrave a aussi marmonné quelque chose à propos d'élémentaires.",
            start = { kind = "npc", id = 9078, name = "Shadowmage Vivian Lagrave", name_fr = "Ombremage Vivian Lagrave", areaID = 3, uiMapID = 1418, x = 2.9, y = 47.76 },
        },
        [4062] = {
            id = 4062, name = "The Rise of the Machines", name_fr = "La révolte des machines", level = 54, requiredLevel = 52, raceMask = 8589934770,
            objective = "Take the Elemental Shard Sample to Lotwil Veriatus.  You recall Theodora saying that Lotwil was stationed in a camp to the east. ", objective_fr = "Apporter l'Echantillon de fragment d'élémentaire à Lotwil Veriatus.  Theodora vous a dit qu'il se trouvait au camp à l'est.",
            start = { kind = "npc", id = 9079, name = "Hierophant Theodora Mulvadania", name_fr = "Hiérophante Theodora Mulvadania", areaID = 3, uiMapID = 1418, x = 3.02, y = 47.81 },
            prerequisitesAny = { { id = 4061, name = "The Rise of the Machines", name_fr = "La révolte des machines" } },
            nextQuest = { id = 4063, name = "The Rise of the Machines", name_fr = "La révolte des machines" },
        },
        [5145] = {
            id = 5145, name = "Dragonscale Leatherworking", name_fr = "Travail du cuir de dragon", level = 55, requiredLevel = 40, raceMask = 8589934770,
            objective = "Bring 2 Tough Scorpid Breastplates, 2 Tough Scorpid Gloves, and 10 Worn Dragonscales to Thorkaf Dragoneye in the Badlands.  Completing this quest will give you access to the Dragonscale Leatherworking arts.  The completion of this quest will prevent you from learning Elemental Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so.", objective_fr = "Apporter 2 Cuirasses armées du scorpide, 2 Gants armés du scorpide et 10 Ecailles de dragon usées à Thorkaf Dragoneye, dans les Terres ingrates.  Terminer cette quête vous donnera accès aux arts du travail du cuir en écailles de dragon.  Terminer cette quête avec succès vous interdira l’apprentissage du travail du cuir élémentaire et du travail du cuir tribal. Prenez le temps de réfléchir à la voie que vous souhaitez emprunter, avant de prendre une décision.",
            start = { kind = "npc", id = 7867, name = "Thorkaf Dragoneye", name_fr = "Thorkaf Dragoneye", areaID = 3, uiMapID = 1418, x = 62.7, y = 57.4 },
        },
        [4134] = {
            id = 4134, name = "Lost Thunderbrew Recipe", name_fr = "La recette perdue de Thunderbrew", level = 55, requiredLevel = 50, raceMask = 8589934770,
