        [3907] = {
            id = 3907, name = "Disharmony of Fire", name_fr = "Discordance des flammes", level = 56, requiredLevel = 48, raceMask = 8589934770,
            objective = "Enter Blackrock Depths and track down Lord Incendius. Slay him and return any source of information you may find to Thunderheart. ", objective_fr = "Pénétrer dans les Profondeurs de Blackrock et traquer le Seigneur Incendius. Le tuer puis donner tous les renseignements que vous pouvez trouver à Thunderheart.",
            start = { kind = "npc", id = 9084, name = "Thunderheart", name_fr = "Thunderheart", areaID = 3, uiMapID = 1418, x = 3.33, y = 48.26 },
            prerequisitesAny = { { id = 3906, name = "Disharmony of Flame", name_fr = "Discordance des flammes" } },
        },
        [4122] = {
            id = 4122, name = "Grark Lorkrub", name_fr = "Grark Lorkrub", level = 58, requiredLevel = 52, raceMask = 8589934770,
            objective = "Travel to the Burning Steppes and find Grark Lorkrub. You recall Lexlort mentioning that he was last seen in a massive Blackrock fortress.  When you find Grark Lorkrub, use the Thorium Shackles to bind him and then lead him back through Blackrock Mountain to the Searing Gorge. Lexlort will have his men waiting on the other side to take Grark into custody. ", objective_fr = "Partez pour les Steppes ardentes et trouvez Grark Lorkrub. Lexlort a mentionné le fait que la dernière fois où on l'a vu, il se trouvait dans une imposante forteresse des Blackrock.  Une fois Grark Lorkrub découvert, l'enchaîner avec les chaînes en thorium, puis le ramener par le mont Blackrock jusque dans la gorge des Vents brûlants. Des hommes de Lexlort attendront de l'autre côté de la gorge et le mettront sous bonne garde.",
            start = { kind = "npc", id = 9080, name = "Lexlort", name_fr = "Lexlort", areaID = 3, uiMapID = 1418, x = 5.88, y = 47.63 },
        },
        [4132] = {
            id = 4132, name = "Operation: Death to Angerforge", name_fr = "Opération : Mort à Forgehargne", level = 58, requiredLevel = 52, raceMask = 8589934770,
            objective = "Travel to Blackrock Depths and slay General Angerforge! Return to Warlord Goretooth when the task is complete.", objective_fr = "Voyagez jusqu'aux Profondeurs de Blackrock et tuez le général Forgehargne ! Une fois votre mission accomplie, retournez voir le seigneur de guerre Goretooth.",
            start = { kind = "npc", id = 9077, name = "Warlord Goretooth", name_fr = "Chef de guerre Goretooth", areaID = 3, uiMapID = 1418, x = 5.81, y = 47.52 },
            prerequisitesAny = { { id = 4121, name = "Precarious Predicament", name_fr = "Situation précaire" } },
        },
        [4063] = {
            id = 4063, name = "The Rise of the Machines", name_fr = "La révolte des machines", level = 58, requiredLevel = 52, raceMask = 8589934770,
            objective = "Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic.", objective_fr = "Trouver et tuer le seigneur des golems Argelmach. Rapporter sa tête à Lotwil. Collecter également 10 Noyaux d'élémentaire intacts sur les Golems ravarage et les Assemblages porteguerre qui protègent Argelmach. Vous savez cela car vous êtes médium.",
            start = { kind = "npc", id = 2921, name = "Lotwil Veriatus", name_fr = "Lotwil Veriatus", areaID = 3, uiMapID = 1418, x = 25.95, y = 44.87 },
            prerequisitesAny = { { id = 4062, name = "The Rise of the Machines", name_fr = "La révolte des machines" } },
        },
        [4981] = {
            id = 4981, name = "Operative Bijou", name_fr = "Agent Bijou", level = 59, requiredLevel = 55, raceMask = 8589934770,
            objective = "Travel to Blackrock Spire and find out what happened to Bijou.", objective_fr = "Aller au Pic Blackrock et découvrir ce qui est arrivé à Bijou.",
            start = { kind = "npc", id = 9080, name = "Lexlort", name_fr = "Lexlort", areaID = 3, uiMapID = 1418, x = 5.88, y = 47.63 },
            nextQuest = { id = 4982, name = "Bijou's Belongings", name_fr = "Les effets de Bijou" },
        },
        [4724] = {
            id = 4724, name = "The Pack Mistress", name_fr = "La maîtresse de meute", level = 59, requiredLevel = 55, raceMask = 8589934770,
            objective = "Slay Halycon, pack mistress of the Bloodaxe worg.", objective_fr = "Tuer Halycon, la maîtresse de la meute des worgs Bloodaxe.",
            start = { kind = "npc", id = 9081, name = "Galamav the Marksman", name_fr = "Galamav le Tireur d'élite", areaID = 3, uiMapID = 1418, x = 5.96, y = 47.73 },
        },
        [4768] = {
            id = 4768, name = "The Darkstone Tablet", name_fr = "La tablette de Darkstone", level = 60, requiredLevel = 57, raceMask = 8589934770,
            objective = "Bring the Darkstone Tablet to Shadow Mage Vivian Lagrave in Kargath.", objective_fr = "Apporter la Tablette de Darkstone à l'ombremage Vivian Lagrave à Kargath.",
            start = { kind = "npc", id = 9078, name = "Shadowmage Vivian Lagrave", name_fr = "Ombremage Vivian Lagrave", areaID = 3, uiMapID = 1418, x = 2.9, y = 47.76 },
            prerequisitesAny = { { id = 4769, name = "Vivian Lagrave and the Darkstone Tablet", name_fr = "Vivian Lagrave et la tablette de Darkstone" } },
        },
        [4903] = {
            id = 4903, name = "Warlord's Command", name_fr = "Ordre du chef de guerre", level = 60, requiredLevel = 55, raceMask = 8589934770,
            objective = "Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished.", objective_fr = "Tuer le généralissime Omokk, le maître de guerre Voone et le seigneur Wyrmthalak. Récupérer les Importants documents Blackrock. Retourner voir le chef de guerre Goretooth à Kargath une fois la mission accomplie.",
            start = { kind = "npc", id = 9077, name = "Warlord Goretooth", name_fr = "Chef de guerre Goretooth", areaID = 3, uiMapID = 1418, x = 5.81, y = 47.52 },
            nextQuest = { id = 4941, name = "Eitrigg's Wisdom", name_fr = "Sagesse d'Eitrigg" },
