        [7583] = {
            id = 7583, name = "Suppression", name_fr = "Suppression", level = 60, requiredLevel = 60, classMask = 256,
            objective = "Venture forth into the Tainted Scar and locate a Doomguard Commander.  Use the Glowing Crystal Prison on the Doomguard Commander. Be prepared for a ferocious onslaught of attacks, as the demon attempts to escape capture.  Should you succeed, return the Imprisoned Doomguard to Daio in the Tainted Scar.", objective_fr = "Pénétrez dans la Balafre impure et localisez un Commandant de la garde funeste.  Servez-vous de la Prison de cristal luminescente sur lui. Attendez-vous à être sauvagement <attaqué/attaquée>, car le démon fera l’impossible pour éviter d’être capturé.  Si vous réussissez, amenez le garde funeste emprisonné à Levadre à la Balafre impure.",
            start = { kind = "npc", id = 14463, name = "Daio the Decrepit", name_fr = "Daio le Décrépit", areaID = 4, uiMapID = 1419, x = 34.13, y = 50.14 },
            prerequisitesAll = { { id = 7581, name = "The Prison's Bindings", name_fr = "Les ancrages de la prison" }, { id = 7582, name = "The Prison's Casing", name_fr = "Les parois de la prison" } },
        },
        [2743] = {
            id = 2743, name = "The Cover of Darkness", name_fr = "Le couvert de l'obscurité", level = 60, requiredLevel = 45,
            objective = "Return to the Fallen Hero of the Horde with your findings.", objective_fr = "Retourner voir le Héros déchu de la Horde avec ces découvertes.",
            start = { kind = "npc", id = 7729, name = "Spirit of Kirith", name_fr = "Esprit de Kirith" },
            prerequisitesAny = { { id = 2721, name = "Kirith", name_fr = "Kirith" } },
            nextQuest = { id = 2744, name = "The Demon Hunter", name_fr = "Le chasseur de démons" },
        },
        [2744] = {
            id = 2744, name = "The Demon Hunter", name_fr = "Le chasseur de démons", level = 60, requiredLevel = 45, special = true,
            objective = "Speak with Loramus Thalipedes in Azshara.", objective_fr = "Aller voir Loramus Thalipedes à Azshara.",
            start = { kind = "npc", id = 7572, name = "Fallen Hero of the Horde", name_fr = "Héros déchu de la Horde", areaID = 8, uiMapID = 1435, x = 34.29, y = 66.14 },
            prerequisitesAny = { { id = 2743, name = "The Cover of Darkness", name_fr = "Le couvert de l'obscurité" } },
            nextQuest = { id = 3141, name = "Loramus", name_fr = "Loramus" },
        },
        [7581] = {
            id = 7581, name = "The Prison's Bindings", name_fr = "Les ancrages de la prison", level = 60, requiredLevel = 60, classMask = 256,
            objective = "Travel to Dire Maul in Feralas and recover 15 Satyr Blood from the Wildspawn Satyr that inhabit the Warpwood Quarter. Return to Daio in the Tainted Scar when this is done. ", objective_fr = "Rendez-vous à Hache-tripes en Feralas et récupérez 15 doses de Sang de satyre sur les satyres Follengeance qui habitent le quartier de Crochebois. Lorsque ce sera fait, retournez voir Levandre à la Balafre impure.",
            start = { kind = "npc", id = 14463, name = "Daio the Decrepit", name_fr = "Daio le Décrépit", areaID = 4, uiMapID = 1419, x = 34.13, y = 50.14 },
            nextQuest = { id = 7583, name = "Suppression", name_fr = "Suppression" },
        },
        [7582] = {
            id = 7582, name = "The Prison's Casing", name_fr = "Les parois de la prison", level = 60, requiredLevel = 60, classMask = 256,
            objective = "Travel to Darkwhisper Gorge in Winterspring and recover 5 Tears of the Hederine from the Hederine demons that occupy the gorge. Return to Daio in the Tainted Scar when you have completed this task.", objective_fr = "Rendez-vous à la gorge du Sombre murmure, dans le Berceau-de-l'Hiver, et récupérez 5 Larmes de l’Hederine sur les démons Hederine qui occupent la gorge. Lorsque ce sera fait, retournez voir Levandre à la Balafre impure.",
            start = { kind = "npc", id = 14463, name = "Daio the Decrepit", name_fr = "Daio le Décrépit", areaID = 4, uiMapID = 1419, x = 34.13, y = 50.14 },
            nextQuest = { id = 7583, name = "Suppression", name_fr = "Suppression" },
        },
        [3627] = {
            id = 3627, name = "Uniting the Shattered Amulet", name_fr = "Réunir les morceaux de l'Amulette brisée.", level = 60, requiredLevel = 45,
            objective = "Slay Grol the Destroyer, Lady Sevine, and Archmage Allistarj. From their corpses take the Amulet of Grol, the Amulet of Sevine, and the Amulet of Allistarj.  Remember to USE your Enchanted Azsharite Fel Weaponry to weaken the triad. They cannot be killed otherwise - but use them wisely... ", objective_fr = "Assassiner Grol le Destructeur, dame Sevine et l'archimage Allistarj. Prendre sur leurs cadavres l'Amulette de Grol, l'Amulette de Sevine et l'Amulette d'Allistarj.  UTILISER les armes Fel en Azsharite enchantée pour affaiblir la triade (ils ne peuvent pas être tués autrement), mais les utiliser sagement...",
            start = { kind = "npc", id = 7572, name = "Fallen Hero of the Horde", name_fr = "Héros déchu de la Horde", areaID = 8, uiMapID = 1435, x = 34.29, y = 66.14 },
            prerequisitesAny = { { id = 3626, name = "Return to the Blasted Lands", name_fr = "Retour aux Terres foudroyées" } },
            nextQuest = { id = 3628, name = "You Are Rakh'likh, Demon", name_fr = "Vous êtes Rakh'likh, démon" },
        },
        [3628] = {
            id = 3628, name = "You Are Rakh'likh, Demon", name_fr = "Vous êtes Rakh'likh, démon", level = 60, requiredLevel = 45,
            objective = "Destroy Razelikh the Defiler and return the Severed Horn of the Defiler to the Fallen Hero of the Horde. You will also need to return the Ward of the Defiler so that the Fallen Hero can destroy it, preventing it from ever falling into the wrong hands. ", objective_fr = "Détruire Razelikh le Souilleur et apporter la Corne brisée du Souilleur au Héros déchu de la Horde. Rendre aussi l'Amulette du Souilleur au Héros Déchu pour qu'il puisse la détruire, afin de l'empêcher de tomber dans de mauvaises mains.",
            start = { kind = "npc", id = 7572, name = "Fallen Hero of the Horde", name_fr = "Héros déchu de la Horde", areaID = 8, uiMapID = 1435, x = 34.29, y = 66.14 },
            prerequisitesAny = { { id = 3627, name = "Uniting the Shattered Amulet", name_fr = "Réunir les morceaux de l'Amulette brisée." } },
        },
    },
}
