            objective = "Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Alexi Barov when you have completed this task.", objective_fr = "S’aventurer jusqu’à Scholomance et récupérer la fortune de la famille Barov. Cette fortune se compose de quatre titres de propriété : le titre de propriété de Caer Darrow ; le titre de propriété de Brill ; le titre de propriété de Moulin-de-Tarren ; et le titre de propriété de Southshore. Revenir auprès d’Alexi Barov quand la tâche est accomplie.",
            start = { kind = "npc", id = 11022, name = "Alexi Barov", name_fr = "Alexi Barov", areaID = 85, uiMapID = 1420, x = 83.06, y = 71.6 },
            nextQuest = { id = 5342, name = "The Last Barov", name_fr = "Le dernier Barov" },
        },
        [8902] = {
            id = 8902, name = "Dearest Elenia,", name_fr = "Très chère Elenia,", level = 60, requiredLevel = 1, raceMask = 8589934770,
            objective = "Deliver the Lovingly Composed Letter to Elenia Haydon near the bank in the Undercity.", objective_fr = "Apporter la Lettre pleine d'amour à Elenia Haydon, près de la banque d’Undercity.",
            start = { kind = "npc", id = 16003, name = "Deathguard Tor", name_fr = "Garde noir Tor", areaID = 85, uiMapID = 1420, x = 60.66, y = 59.48 },
        },
        [8652] = {
            id = 8652, name = "Graveborn the Elder", name_fr = "L'Ancien Graveborn", level = 60, requiredLevel = 1,
            start = { kind = "npc", id = 15568, name = "Elder Graveborn", name_fr = "Ancien Graveborn", areaID = 85, uiMapID = 1420, x = 61.87, y = 53.84 },
        },
        [8322] = {
            id = 8322, name = "Rotten Eggs", name_fr = "Les œufs pourris", level = 60, requiredLevel = 30, raceMask = 8589934770,
            objective = "Place the Rotten Eggs in the main brew keg located inside the Southshore Inn.", objective_fr = "Placez les Oeufs pourris dans le tonneau de bière principal de l’auberge de Southshore.",
            start = { kind = "npc", id = 15197, name = "Darkcaller Yanka", name_fr = "Sombre imploratrice Yanka", areaID = 85, uiMapID = 1420, x = 55.58, y = 69.9 },
            nextQuest = { id = 8409, name = "Ruined Kegs", name_fr = "Des tonneaux gâtés" },
        },
        [1657] = {
            id = 1657, name = "Stinking Up Southshore", name_fr = "Empuantir Southshore", level = 60, requiredLevel = 25, raceMask = 8589934770,
            objective = "Toss three Forsaken Stink Bombs into the heart of Southshore in Hillsbrad, and return to Darkcaller Yanka at the Wickerman Festival in Tirisfal Glade.", objective_fr = "Lancer trois Boules puantes des Réprouvés au milieu de Southshore en Hillsbrad, puis revenez voir la sombre imploratrice Yanka à la Fête de l’homme d’osier, aux Clairières de Tirisfal.",
            start = { kind = "npc", id = 15197, name = "Darkcaller Yanka", name_fr = "Sombre imploratrice Yanka", areaID = 85, uiMapID = 1420, x = 55.58, y = 69.9 },
        },
    },
}
