            objective = "Proceed to the Scarlet Crusade's base camp between Felstone Field and Dalson's Tears and destroy their command tent.  Place the Scourge banner at the camp, and then return to High Executor Derrington at the Bulwark, Western Plaguelands.", objective_fr = "Se rendre au camp de base de la Croisade écarlate situé entre le Champ de Felstone et les Larmes de Dalson et détruire leur tente d’état-major.  Placer la bannière du Fléau sur le camp, puis revenir auprès du Grand exécuteur Derrington à la Barricade, dans les Maleterres de l’ouest.",
            start = { kind = "npc", id = 10837, name = "High Executor Derrington", name_fr = "Grand exécuteur Derrington", areaID = 85, uiMapID = 1420, x = 83.13, y = 68.94 },
            prerequisitesAny = { { id = 5093, name = "A Call to Arms: The Plaguelands!", name_fr = "Un appel aux armes : les Maleterres" }, { id = 5094, name = "A Call to Arms: The Plaguelands!", name_fr = "Un appel aux armes : les Maleterres" }, { id = 5095, name = "A Call to Arms: The Plaguelands!", name_fr = "Un appel aux armes : les Maleterres" } },
        },
        [5216] = {
            id = 5216, name = "Target: Felstone Field", name_fr = "Cible : le Champ de Felstone", level = 53, requiredLevel = 50, raceMask = 4294967373,
            objective = "Go to Felstone Field in Western Plaguelands to locate and defeat the Cauldron Lord present there. It may have a key that will allow access to the cauldron. You must have the Empty Felstone Field Bottle with you to secure a sample of the poisons used inside the cauldron.", objective_fr = "Se rendre au Champ de Felstone dans les Maleterres de l’ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve. Il aura peut-être une clé qui permet d’accéder au chaudron. Il faut se munir de la Bouteille d'échantillon du Champ de Felstone vide pour pouvoir prélever un échantillon des poisons qui sont dans le chaudron.",
            start = { kind = "npc", id = 11053, name = "High Priestess MacDonnell", name_fr = "Grande prêtresse MacDonnell", areaID = 28, uiMapID = 1422, x = 42.97, y = 84.5 },
            prerequisitesAny = { { id = 5215, name = "The Scourge Cauldrons", name_fr = "Les chaudrons du Fléau" } },
