        [4971] = {
            id = 4971, name = "A Matter of Time", name_fr = "Une question de temps", level = 56, requiredLevel = 53,
            objective = "Use the Temporal Displacer near one of Andorhal's silos and uncover Temporal Parasites.  Slay 10 Temporal Parasites, and then return the Temporal Displacer to Chromie in the Andorhal Inn, Western Plaguelands.", objective_fr = "Utiliser le Déplaceur temporel à côté de l’un des silos d’Andorhal pour révéler des Parasites temporels.  Tuer 15 Parasites temporels et rapporter le Déplaceur temporel à Chromie, à l’auberge d’Andorhal, dans les Maleterres de l’ouest.",
