        },
        [5097] = {
            id = 5097, name = "All Along the Watchtowers", name_fr = "Tout au long des tours de guet", level = 56, requiredLevel = 50, raceMask = 4294967373,
            objective = "Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it.  Once all four towers are marked, return the Beacon Torch to Commander Ashlam Valorfist in Chillwind Camp, Western Plaguelands.", objective_fr = "À l’aide de la Torche-balise, marquer chaque tour à Andorhal ; il faut se tenir dans l’embrasure de la porte de la tour pour pouvoir la marquer.  Quand les quatre tours seront marquées, rapporter la Torche-balise au commandant Ashlam Valorfist au camp du Noroît, dans les Maleterres de l’ouest.",
            start = { kind = "npc", id = 10838, name = "Commander Ashlam Valorfist", name_fr = "Commandant Ashlam Valorfist", areaID = 28, uiMapID = 1422, x = 42.7, y = 84.03 },
            prerequisitesAny = { { id = 5092, name = "Clear the Way", name_fr = "Nettoyer le passage" } },
