        [5343] = {
            id = 5343, name = "Barov Family Fortune", name_fr = "Fortune de la famille Barov", level = 60, requiredLevel = 52, raceMask = 4294967373,
            objective = "Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Weldon Barov when you have completed this task.", objective_fr = "S’aventurer jusqu’à la Scholomance et récupérer la fortune de la famille Barov. Cette fortune se compose de quatre titres de propriété : le titre de propriété de Caer Darrow ; le titre de propriété de Brill ; le titre de propriété de Moulin-de-Tarren ; et le titre de propriété de Southshore. Revenir auprès de Weldon Barov quand la tâche est accomplie.",
            start = { kind = "npc", id = 11023, name = "Weldon Barov", name_fr = "Weldon Barov", areaID = 28, uiMapID = 1422, x = 43.45, y = 83.73 },
            nextQuest = { id = 5344, name = "The Last Barov", name_fr = "Le dernier Barov" },
        },
        [5166] = {
            id = 5166, name = "Breastplate of the Chromatic Flight", name_fr = "La cuirasse du vol chromatique", level = 60, requiredLevel = 57,
            objective = "To forge the Breastplate of the Chromatic Flight, you will be required to bring the following items to Jeziba the 'Sculptor':  1 Chromatic Carapace.  10 Brilliant Chromatic Scales.  10 Blood of Heroes.  10 Frayed Abomination Stitchings.", objective_fr = "Pour forger la Cuirasse du vol chromatique, il faut apporter les éléments suivants à Jeziba le 'Sculpteur' :  1 Carapace chromatique.  10 Ecailles chromatiques brillantes.  10 Sangs de héros.  10 Coutures d'Abomination effilochées.",
            start = { kind = "object", id = 176192, name = "Catalogue of the Wayward", name_fr = "Catalogue de Wayward", areaID = 28, uiMapID = 1422, x = 39.35, y = 66.6 },
