        [5382] = {
            id = 5382, name = "Doctor Theolen Krastinov, the Butcher", name_fr = "Docteur Theolen Krastinov, le boucher", level = 60, requiredLevel = 55,
            objective = "Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete. ", objective_fr = "Trouver le docteur Theolen Krastinov à l’intérieur de la Scholomance. Le tuer, puis brûler le Cadavre d’Eva Sarkhoff et le Cadavre de Lucien Sarkhoff. Retourner auprès d’Eva Sarkhoff quand la tâche est accomplie.",
            start = { kind = "npc", id = 11216, name = "Eva Sarkhoff", name_fr = "Eva Sarkhoff", areaID = 28, uiMapID = 1422, x = 70.22, y = 73.71 },
            nextQuest = { id = 5515, name = "Krastinov's Bag of Horrors", name_fr = "Sac des horreurs de Krastinov" },
        },
        [5861] = {
            id = 5861, name = "Find Myranda", name_fr = "Trouver Myranda", level = 60, requiredLevel = 52,
            objective = "Travel to Uther's Tomb, located in the southern Plaguelands. Show Myranda the Hag Tirion's Gift.", objective_fr = "Se rendre au tombeau d’Uther, au sud des Maleterres. Montrer à Myranda la Mégère le Don de Tirion.",
            start = { kind = "npc", id = 1855, name = "Tirion Fordring", name_fr = "Tirion Fordring", areaID = 139, uiMapID = 1423, x = 5.16, y = 35.57 },
            prerequisitesAny = { { id = 5848, name = "Of Love and Family", name_fr = "De l'amour et de la famille" } },
            nextQuest = { id = 5862, name = "Scarlet Subterfuge", name_fr = "Le subterfuge écarlate" },
        },
        [6184] = {
            id = 6184, name = "Flint Shadowmore", name_fr = "Flint Shadowmore", level = 60, requiredLevel = 56, raceMask = 4294967373,
            objective = "Travel to Chillwind Camp in the Western Plaguelands and meet up with your contact, Flint Shadowmore. ", objective_fr = "Allez au camp du Noroît, dans les Maleterres de l’ouest, et rencontrez votre contact, Flint Shadowmore.",
            start = { kind = "npc", id = 332, name = "Master Mathias Shaw", name_fr = "Maître Mathias Shaw", areaID = 1519, uiMapID = 1453, x = 78.31, y = 70.74 },
            prerequisitesAny = { { id = 6183, name = "Honor the Dead", name_fr = "Honorer la mort" } },
