        [5944] = {
            id = 5944, name = "In Dreams", name_fr = "En rêves", level = 60, requiredLevel = 52, special = true,
            objective = "Escort Taelan Fordring out of Hearthglen.", objective_fr = "Escortez Taelan Fordring jusqu'à la sortie des Hearthglen.",
            start = { kind = "npc", id = 1842, name = "Highlord Taelan Fordring", name_fr = "Généralissime Taelan Fordring", areaID = 28, uiMapID = 1422, x = 42.02, y = 14.79 },
            prerequisitesAny = { { id = 5862, name = "Scarlet Subterfuge", name_fr = "Le subterfuge écarlate" } },
        },
        [5384] = {
            id = 5384, name = "Kirtonos the Herald", name_fr = "Kirtonos le héraut", level = 60, requiredLevel = 55,
            objective = "Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul.  Fight valiantly, do not give an inch! Destroy Kirtonos and return to Eva Sarkhoff. ", objective_fr = "Revenir à Scholomance avec le Sang des innocents. Trouver le porche et placer le Sang des innocents dans le brasero. Kirtonos viendra dévorer votre âme.  Combattre vaillamment, sans perdre un pouce de terrain ! Détruire Kirtonos et revenir auprès d’Eva Sarkhoff.",
            start = { kind = "npc", id = 11216, name = "Eva Sarkhoff", name_fr = "Eva Sarkhoff", areaID = 28, uiMapID = 1422, x = 70.22, y = 73.71 },
            prerequisitesAny = { { id = 5515, name = "Krastinov's Bag of Horrors", name_fr = "Sac des horreurs de Krastinov" } },
        },
        [5515] = {
            id = 5515, name = "Krastinov's Bag of Horrors", name_fr = "Sac des horreurs de Krastinov", level = 60, requiredLevel = 55,
            objective = "Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff.", objective_fr = "Trouver Jandice Barov dans Scholomance et la tuer. Sur son cadavre, récupérer le Sac des horreurs de Krastinov. Rapporter le sac à Eva Sarkhoff.",
            start = { kind = "npc", id = 11216, name = "Eva Sarkhoff", name_fr = "Eva Sarkhoff", areaID = 28, uiMapID = 1422, x = 70.22, y = 73.71 },
            prerequisitesAny = { { id = 5382, name = "Doctor Theolen Krastinov, the Butcher", name_fr = "Docteur Theolen Krastinov, le boucher" } },
            nextQuest = { id = 5384, name = "Kirtonos the Herald", name_fr = "Kirtonos le héraut" },
        },
        [5167] = {
            id = 5167, name = "Legplates of the Chromatic Defier", name_fr = "Cuissardes des duellistes chromatiques", level = 60, requiredLevel = 57,
            objective = "To forge the Legplates of the Chromatic Defier, you will be required to bring the following items to Jeziba the 'Sculptor':  1 Chromatic Carapace.  10 Brilliant Chromatic Scales.  10 Blood of Heroes.  5 Skin of Shadow.", objective_fr = "Pour forger les Cuissardes des duellistes chromatiques, il faut apporter les éléments suivants à Jeziba le 'Sculpteur' :  1 Carapace chromatique.  10 Ecailles chromatiques brillantes.  10 Sangs de héros.  5 Peaux des ombres.",
