        [6569] = {
            id = 6569, name = "Oculus Illusions", name_fr = "Illusions d'Occulus", level = 60, requiredLevel = 55, raceMask = 8589934770,
            objective = "Travel to Blackrock Spire and collect 20 Black Dragonspawn Eyes. Return to Myranda the Hag when the task is complete.", objective_fr = "Aller au Pic Blackrock et collecter 20 Yeux de draconide noir. Retourner voir Myranda la Mégère, quand la tâche sera terminée.",
            start = { kind = "npc", id = 11872, name = "Myranda the Hag", name_fr = "Myranda la Mégère", areaID = 28, uiMapID = 1422, x = 50.79, y = 77.85 },
            prerequisitesAny = { { id = 6568, name = "The Testament of Rexxar", name_fr = "Le testament de Rexxar" } },
            nextQuest = { id = 6570, name = "Emberstrife", name_fr = "Brandeguerre" },
        },
        [5848] = {
            id = 5848, name = "Of Love and Family", name_fr = "De l'amour et de la famille", level = 60, requiredLevel = 52,
            objective = "Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world.  Return the painting to Tirion Fordring.", objective_fr = "Se rendre à Stratholme, dans la partie nord des Maleterres. C’est dans le Bastion écarlate que se trouve le tableau De l'amour et de la famille, caché derrière une autre peinture représentant les lunes jumelles.  Rapporter le tableau à Tirion Fordring.",
            start = { kind = "npc", id = 11936, name = "Artist Renfray", name_fr = "Artiste Renfray", areaID = 28, uiMapID = 1422, x = 65.77, y = 75.37 },
            prerequisitesAny = { { id = 5846, name = "Of Love and Family", name_fr = "L'amour et la famille" } },
            nextQuest = { id = 5861, name = "Find Myranda", name_fr = "Trouver Myranda" },
        },
        [5862] = {
            id = 5862, name = "Scarlet Subterfuge", name_fr = "Le subterfuge écarlate", level = 60, requiredLevel = 52,
            objective = "Speak to Myranda to gain the Scarlet Illusion. Travel to Hearthglen while under the Scarlet Illusion and deliver Tirion's Gift to Highlord Taelan Fordring.  Hearthglen is to the north, Taelan should be inside of Mardenholde Keep.", objective_fr = "Parler à Myranda pour obtenir l’Illusion écarlate. Aller à Hearthglen pendant que vous êtes sous l’effet de l’Illusion écarlate, et apporter le Don de Tirion au généralissime Taelan Fordring.  Hearthglen se trouve au nord, et Taelan devrait se trouver à l’intérieur du Donjon de Mardenholde.",
            start = { kind = "npc", id = 11872, name = "Myranda the Hag", name_fr = "Myranda la Mégère", areaID = 28, uiMapID = 1422, x = 50.79, y = 77.85 },
            prerequisitesAny = { { id = 5861, name = "Find Myranda", name_fr = "Trouver Myranda" } },
        },
        [5465] = {
            id = 5465, name = "Soulbound Keepsake", name_fr = "Souvenir lié", level = 60, requiredLevel = 57,
            objective = "Return to Magistrate Marduke in Caer Darrow. Show him the Soulbound Keepsake.", objective_fr = "Retourner auprès du Magistrat Marduke à Caer Darrow. Lui montrer le Souvenir lié.",
            start = { kind = "npc", id = 11036, name = "Leonid Barthalomew the Revered", name_fr = "Leonid Barthalomew le Révéré", areaID = 139, uiMapID = 1423, x = 71.89, y = 48.29 },
            prerequisitesAny = { { id = 5464, name = "Menethil's Gift", name_fr = "Le cadeau de Menethil" } },
            nextQuest = { id = 5466, name = "The Lich, Ras Frostwhisper", name_fr = "La Liche, Ras Murmegivre" },
        },
        [5462] = {
            id = 5462, name = "The Dying, Ras Frostwhisper", name_fr = "Le moribond, Ras Murmegivre", level = 60, requiredLevel = 57,
            objective = "Travel to Light's Hope in Eastern Plaguelands and seek out Leonid Barthalomew the Revered. Show him the Keepsake of Remembrance and tell him all that you have discovered.", objective_fr = "Voyager jusqu’à l’Espoir de lumière dans les Maleterres de l'est et trouver Leonid Barthalomew le Révéré. Lui montrer le Souvenir de la mémoire et lui dire tout ce que vous avez découvert.",
            start = { kind = "npc", id = 11286, name = "Magistrate Marduke", name_fr = "Magistrat Marduke", areaID = 28, uiMapID = 1422, x = 70.57, y = 74.11 },
            prerequisitesAny = { { id = 5461, name = "The Human, Ras Frostwhisper", name_fr = "L'humain, Ras Murmegivre" } },
            nextQuest = { id = 5463, name = "Menethil's Gift", name_fr = "Le cadeau de Menethil" },
        },
        [5461] = {
            id = 5461, name = "The Human, Ras Frostwhisper", name_fr = "L'humain, Ras Murmegivre", level = 60, requiredLevel = 57,
            objective = "Travel to the Arathi Highlands, to the ruins of Stromgarde. Search Stromgarde for a Keepsake of Remembrance. If you find such an item, return with it to Magistrate Marduke.", objective_fr = "Voyager jusqu’aux hautes-terres d'Arathi, et aller aux ruines de Stromgarde. Fouiller Stromgarde pour trouver un Souvenir de la mémoire. Si une telle trouvaille est faite, rapporter l’objet au magistrat Marduke.",
            start = { kind = "npc", id = 11286, name = "Magistrate Marduke", name_fr = "Magistrat Marduke", areaID = 28, uiMapID = 1422, x = 70.57, y = 74.11 },
            prerequisitesAny = { { id = 5384, name = "Kirtonos the Herald", name_fr = "Kirtonos le héraut" } },
            nextQuest = { id = 5462, name = "The Dying, Ras Frostwhisper", name_fr = "Le moribond, Ras Murmegivre" },
        },
        [5505] = {
            id = 5505, name = "The Key to Scholomance", name_fr = "La clé de Scholomance", level = 60, requiredLevel = 55, raceMask = 4294967373,
            start = { kind = "npc", id = 11056, name = "Alchemist Arbington", name_fr = "Alchimiste Arbington", areaID = 28, uiMapID = 1422, x = 42.66, y = 83.77 },
            prerequisitesAny = { { id = 5803, name = "Araj's Scarab", name_fr = "Le Scarabée d'Araj" } },
        },
        [5511] = {
            id = 5511, name = "The Key to Scholomance", name_fr = "La clé de Scholomance", level = 60, requiredLevel = 55, raceMask = 8589934770,
            start = { kind = "npc", id = 10837, name = "High Executor Derrington", name_fr = "Grand exécuteur Derrington", areaID = 85, uiMapID = 1420, x = 83.13, y = 68.94 },
            prerequisitesAny = { { id = 5804, name = "Araj's Scarab", name_fr = "Le Scarabée d'Araj" } },
        },
        [5342] = {
            id = 5342, name = "The Last Barov", name_fr = "Le dernier Barov", level = 60, requiredLevel = 52, raceMask = 8589934770,
            objective = "Travel to Chillwind Camp - Alliance territory - and assassinate Weldon Barov. Take his head and return to Alexi Barov.  Be warned, Weldon will probably be well protected by Alliance scum.", objective_fr = "Voyagez jusqu’au Camp du Noroît, dans le territoire de l’Alliance, et y assassiner Weldon Barov. Prenez sa tête et revenez auprès d’Alexi Barov.  Attention : Weldon sera probablement bien protégé par la racaille de l’Alliance.",
            start = { kind = "npc", id = 11022, name = "Alexi Barov", name_fr = "Alexi Barov", areaID = 85, uiMapID = 1420, x = 83.06, y = 71.6 },
            prerequisitesAny = { { id = 5341, name = "Barov Family Fortune", name_fr = "Fortune de la famille Barov" } },
        },
        [5344] = {
            id = 5344, name = "The Last Barov", name_fr = "Le dernier Barov", level = 60, requiredLevel = 52, raceMask = 4294967373,
            objective = "Travel to the Bulwark - Horde territory - and assassinate Alexi Barov. Take his head and return to Weldon Barov.  Be warned, Alexi will probably be well protected by Horde filth.", objective_fr = "Voyager jusqu’à la Barricade - territoire de la Horde - et assassiner Alexi Barov. Prendre sa tête et revenir auprès de Weldon Barov.  Attention : Alexi sera probablement bien protégé par les vandales de la Horde.",
            start = { kind = "npc", id = 11023, name = "Weldon Barov", name_fr = "Weldon Barov", areaID = 28, uiMapID = 1422, x = 43.45, y = 83.73 },
            prerequisitesAny = { { id = 5343, name = "Barov Family Fortune", name_fr = "Fortune de la famille Barov" } },
        },
        [5466] = {
            id = 5466, name = "The Lich, Ras Frostwhisper", name_fr = "La Liche, Ras Murmegivre", level = 60, requiredLevel = 57,
            objective = "Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke.", objective_fr = "Trouver Ras Murmegivre dans Scholomance. Après l’avoir trouvé, utiliser le Souvenir lié sur son visage mort-vivant. Si sa transformation en mortel réussit, l’abattre et prendre la Tête humaine de Ras Murmegivre. Apporter la tête au Magistrat Marduke.",
            start = { kind = "npc", id = 11286, name = "Magistrate Marduke", name_fr = "Magistrat Marduke", areaID = 28, uiMapID = 1422, x = 70.57, y = 74.11 },
            prerequisitesAny = { { id = 5465, name = "Soulbound Keepsake", name_fr = "Souvenir lié" } },
        },
        [5162] = {
            id = 5162, name = "Wrath of the Blue Flight", name_fr = "La colère du vol bleu", level = 60, requiredLevel = 57,
            objective = "Speak with Jeziba in the Plaguelands. He resides in Andorhal.", objective_fr = "Parler à Jeziba dans les Maleterres. Il vit à Andorhal.",
            start = { kind = "npc", id = 10929, name = "Haleh", name_fr = "Haleh", areaID = 618, uiMapID = 1452, x = 54.55, y = 51.2 },
            prerequisitesAny = { { id = 5161, name = "Wrath of the Blue Flight", name_fr = "La colère du vol bleu" } },
            nextQuest = { id = 5164, name = "Catalogue of the Wayward", name_fr = "Guide de l'Indocile" },
        },
    },
}
