        [6026] = {
            id = 6026, name = "That's Asking A Lot", name_fr = "Cela demande beaucoup", level = 58, requiredLevel = 54,
            objective = "Smokey LaRue wants you to get 2 Thorium Bars, 1 Golden Rod, 8 Hi-Explosive Bombs, and 8 Unstable Triggers.  You will have to find a blacksmith and an engineer for these items.", objective_fr = "Smokey LaRue veut que vous lui apportiez 2 Barres de thorium, 1 Bâtonnet doré, 8 Bombes explosives et 8 Déclencheurs instables.  Vous devrez trouver un forgeron et un ingénieur pour obtenir ces objets.",
            start = { kind = "npc", id = 11033, name = "Smokey LaRue", name_fr = "Smokey LaRue", areaID = 139, uiMapID = 1423, x = 70.88, y = 48.43 },
