        [6022] = {
            id = 6022, name = "To Kill With Purpose", name_fr = "Tuer utile", level = 58, requiredLevel = 54, raceMask = 8589934770,
            objective = "Travel to Corin's Crossing to the east and slaughter the Scourge that inhabit the town. Collect 7 pieces of Living Rot in under 10 minutes. Use the Mortar and Pestle to grind the Living Rot into Coagulated Rot.", objective_fr = "Allez à l'est à la Croisée de Corin et détruisez les membres du Fléau qui habitent la ville. Rassemblez sept morceaux de Pourriture vivante en moins de dix minutes. Utilisez le Mortier et le pilon pour réduire la Pourriture vivante en Pourriture coagulée.",
            start = { kind = "npc", id = 11878, name = "Nathanos Blightcaller", name_fr = "Nathanos le Flétrisseur", areaID = 139, uiMapID = 1423, x = 22.23, y = 63.51 },
        },
        [5248] = {
