            objective = "Take the Crystal of Zin-Malor to Lake Kel'Theril in Winterspring and find a highborne spirit that will speak to you.", objective_fr = "Amener le Cristal de Zin-Malor au lac Kel'Theril dans le Berceau-de-l'Hiver et trouver un esprit Bien-né qui veuille bien vous parler.",
            start = { kind = "npc", id = 10304, name = "Aurora Skycaller", name_fr = "Aurora Skycaller", areaID = 139, uiMapID = 1423, x = 46.49, y = 16.03 },
