        [6042] = {
            id = 6042, name = "Un-Life's Little Annoyances", name_fr = "Les petits soucis de la non-vie", level = 58, requiredLevel = 54, raceMask = 8589934770,
            objective = "Slay 20 Noxious Plaguebats and 10 Monstrous Plaguebats. Return to Nathanos Blightcaller when you are finished.", objective_fr = "Tuer 20 Chauves-souris pestiférées nuisibles et 10 Chauves-souris pestiférées monstrueuses. Retourner voir Nathanos le Flétrisseur quand ce sera fait.",
            start = { kind = "npc", id = 11878, name = "Nathanos Blightcaller", name_fr = "Nathanos le Flétrisseur", areaID = 139, uiMapID = 1423, x = 22.23, y = 63.51 },
        },
        [6041] = {
            id = 6041, name = "When Smokey Sings, I Get Violent", name_fr = "Quand Smokey chante, je deviens violent", level = 58, requiredLevel = 54,
            objective = "Travel to Plaguewood, northwest of Light's Hope. Destroy 8 Scourge Structures by using Smokey's Special Compound at the Mark of Detonation planted inside each building. Smokey has had the Ziggurats and Slaughterhouses marked.  Once you plant the bomb, leave the building and marvel at your handiwork.  By the way, Smokey's Special Compound is rather... unstable.", objective_fr = "Aller à Pestebois, au nord-ouest de la chapelle de l'Espoir de Lumière. Détruire 8 Bâtiments du Fléau en utilisant le Mélange spécial de Smokey sur les Marques de détonation que portent les bâtiments destinés à être détruits. Smokey a fait marquer les ziggourats et les abattoirs.  Une fois la bombe placée, quitter le bâtiment et contempler le résultat de votre opération.  Garder en tête que le Mélange spécial de Smokey est très... instable.",
            start = { kind = "npc", id = 11033, name = "Smokey LaRue", name_fr = "Smokey LaRue", areaID = 139, uiMapID = 1423, x = 70.88, y = 48.43 },
            prerequisitesAny = { { id = 6026, name = "That's Asking A Lot", name_fr = "Cela demande beaucoup" } },
        },
