        [6187] = {
            id = 6187, name = "Order Must Be Restored", name_fr = "L'ordre doit être rétabli", level = 60, requiredLevel = 56, raceMask = 4294967373,
            objective = "Assemble an army and travel to the Eastern Plaguelands. Launch a full assault on Nathanos Blightcaller and any Horde filth that may attempt to protect him.  Keep your wits about you, $N. The Horde will defend the ranger lord with their very lives.", objective_fr = "Montez une armée et portez-vous vers les Maleterres de l’est. Lancez un assaut total sur Nathanos le Flétrisseur et détruisez tout misérable élément de la Horde qui tenterait de le défendre.  Gardez votre présence d’esprit, <nom> : la Horde le défendra jusqu’à la mort.",
            start = { kind = "npc", id = 1748, name = "Highlord Bolvar Fordragon", name_fr = "Généralissime Bolvar Fordragon", areaID = 1519, uiMapID = 1453, x = 80.21, y = 38.35 },
            prerequisitesAny = { { id = 6186, name = "The Blightcaller Cometh", name_fr = "La venue du Flétrisseur" } },
