            id = 6133, name = "The Ranger Lord's Behest", name_fr = "L'ordre du seigneur forestier", level = 60, requiredLevel = 54, raceMask = 8589934770,
            objective = "Travel to the northern borders of the Eastern Plaguelands and recover the Quel'Thalas Registry. The item is somewhere in the Quel'Lithien lodge.  You must also slay 8 Rangers, 8 Pathstriders, and 8 Woodsmen.", objective_fr = "Aller vers la frontière nord des Maleterres de l’est et récupérer le Registre de Quel'Thalas. L’objet se trouve quelque part dans le gîte de Quel'Lithien.  Tuer également 8 Forestiers, 8 Eclaireurs et 8 Bûcherons.",
            start = { kind = "npc", id = 11878, name = "Nathanos Blightcaller", name_fr = "Nathanos le Flétrisseur", areaID = 139, uiMapID = 1423, x = 22.23, y = 63.51 },
        },
        [5281] = {
            id = 5281, name = "The Restless Souls", name_fr = "Âmes tourmentées", level = 60, requiredLevel = 55,
            objective = "Find Egan. You only know that he was last seen around Stratholme.", objective_fr = "Trouver Egan. Vous savez seulement qu’on l’a vu pour la dernière fois aux alentours de Stratholme.",
