            nextQuest = { id = 5282, name = "The Restless Souls", name_fr = "Âmes tourmentées" },
        },
        [5282] = {
            id = 5282, name = "The Restless Souls", name_fr = "Âmes tourmentées", level = 60, requiredLevel = 55,
            objective = "Use Egan's Blaster on the ghostly and spectral citizens of Stratholme. When the restless souls break free from their ghostly shells, use the blaster again - freedom will be theirs!  Free 15 Restless Souls and return to Egan.", objective_fr = "Se servir du Libérateur d'Egan sur les citoyens fantomatiques et spectraux de Stratholme. Quand les esprits sans repos se libèrent de leur enveloppes fantomatiques, utiliser de nouveau le Libérateur – ils seront enfin libres !  Libérer 15 Esprits sans repos puis retourner auprès d’Egan.",
            start = { kind = "npc", id = 11140, name = "Egan", name_fr = "Egan", areaID = 139, uiMapID = 1423, x = 11.36, y = 26.6 },
            prerequisitesAny = { { id = 5281, name = "The Restless Souls", name_fr = "Âmes tourmentées" } },
        },
        [6148] = {
            id = 6148, name = "The Scarlet Oracle, Demetria", name_fr = "L'Oracle écarlate, Demetria", level = 60, requiredLevel = 56, raceMask = 8589934770,
            objective = "The Scarlet Crusade is on the move. Somewhere along the road from Tyr's Hand to Stratholme you will find the Oracle, Demetria, and her entourage. Hunt her down and slay her. Return to Nathanos Blightcaller should you succeed.", objective_fr = "La Croisade écarlate fait mouvement. Quelque part le long de la route, entre la Main de Tyr et Stratholm, vous trouverez l’Oracle Demetria et sa fratrie. La tuer et retourner voir Nathanos le Flétrisseur.",
            start = { kind = "npc", id = 11878, name = "Nathanos Blightcaller", name_fr = "Nathanos le Flétrisseur", areaID = 139, uiMapID = 1423, x = 22.23, y = 63.51 },
            prerequisitesAny = { { id = 6147, name = "Return to Nathanos", name_fr = "Retourner voir Nathanos" } },
        },
