        },
        [9153] = {
            id = 9153, name = "Under the Shadow", name_fr = "Sous les ombres", level = 60, requiredLevel = 58,
            objective = "Check your map to find an area under Scourge attack. Go there and damage a necropolis by defeating the Scourge around them. Return 10 of their Necrotic Runes to Commander Thomas Helleran at Light's Hope Chapel in the Eastern Plaguelands.", objective_fr = "Surveillez votre carte pour trouver une région subissant une attaque du Fléau. Allez-y et endommagez une nécropole en exterminant les créatures du Fléau aux alentours. Rapportez ensuite 10 de leurs Runes nécrotiques au commandant Thomas Helleran, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’est.",
            start = { kind = "npc", id = 16361, name = "Commander Thomas Helleran", name_fr = "Commandant Thomas Helleran", areaID = 139, uiMapID = 1423, x = 71.15, y = 50.61 },
        },
