        [7842] = {
            id = 7842, name = "Another Message to the Wildhammer", name_fr = "Encore un message pour les Wildhammer", level = 48, requiredLevel = 44, raceMask = 8589934770,
            objective = "Otho Moji'ko at Revantusk Village in the Hinterlands wants you to bring him 10 Long Elegant Feathers from the gryphons that inhabit the Hinterlands. Return to him once this task is complete.  Gryphons are known to inhabit every region of the Hinterlands.", objective_fr = "Otho Moji'ko, du village des Revantusk dans les Hinterlands, vous demande de lui ramener 10 Longues plumes élégantes prélevées sur les gryphons qui vivent dans les Hinterlands. Retournez le voir lorsque vous les aurez.  On trouve des gryphons dans tous les Hinterlands.",
