            prerequisitesAny = { { id = 7841, name = "Message to the Wildhammer", name_fr = "Un message pour les Wildhammer" } },
            nextQuest = { id = 7843, name = "The Final Message to the Wildhammer", name_fr = "Le message final pour les Wildhammer" },
        },
        [7830] = {
            id = 7830, name = "Avenging the Fallen", name_fr = "Venger les victimes", level = 48, requiredLevel = 44, raceMask = 8589934770,
            objective = "Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill a Razorbeak Skylord and retrieve its Skylord Plume. Return to him once the task is complete.  Markhor mentioned that the Razorbeak Skylord are a rare breed that tend to occupy the wilds of the Hinterlands.", objective_fr = "Le veneur Markhor, du village des Revantusk des Hinterlands, veut que vous tuiez un Seigneur du ciel Bec-rasoir et que vous récupériez une Plume de Seigneur du ciel. Revenez le voir lorsque vous aurez terminé votre tâche.  D’après Makhor, les Seigneurs du ciel Bec-rasoir sont des créatures rares qui vivent dans les régions sauvages des Hinterlands.",
            start = { kind = "npc", id = 14741, name = "Huntsman Markhor", name_fr = "Veneur Markhor", areaID = 47, uiMapID = 1425, x = 79.16, y = 79.53 },
        },
        [7844] = {
            id = 7844, name = "Cannibalistic Cousins", name_fr = "Les cousins cannibales", level = 48, requiredLevel = 44, raceMask = 8589934770,
            objective = "Mystic Yayo'jin at Revantusk Village in the Hinterlands wants you to kill 30 Vilebranch Scalpers and 15 Vilebranch Soothsayers. Return to her when this task is complete.  Yayo'jin indicated that these trolls could be found near the Shaol'watha and Agol'watha temples in the north by northeastern region of the Hinterlands.", objective_fr = "Yayo’jin la Mystique, du village des Revantusk des Hinterlands, veut que tuiez 30 Scalpeurs Vilebranch et 15 Devins Vilebranch. Retournez la voir lorsque vous aurez terminé.  D’après Yayo’jin, ces trolls se trouvent près des temples de Shaol'watha et d’Agol'watha, au nord-nord-est des Hinterlands.",
            start = { kind = "npc", id = 14739, name = "Mystic Yayo'jin", name_fr = "Yayo'jin la Mystique", areaID = 47, uiMapID = 1425, x = 78.8, y = 78.25 },
        },
        [485] = {
            id = 485, name = "Find OOX-09/HL!", name_fr = "Trouver OOX-09/HL !", level = 48, requiredLevel = 43,
            objective = "Take the distress beacon to Oglethorpe's homing robot at the head of the river in the Hinterlands, near Skulk Rock.", objective_fr = "Apporter la balise de détresse jusqu'au robot guidé d'Oglethorpe en haut de la rivière dans les Hinterlands, près du rocher de l'Affût.",
            start = { kind = "item", id = 8704, name = "OOX-09/HL Distress Beacon", name_fr = "Balise de détresse OOX-09/HL" },
            nextQuest = { id = 836, name = "Rescue OOX-09/HL!", name_fr = "À la rescousse de OOX-09/HL !" },
        },
        [7816] = {
            id = 7816, name = "Gammerita, Mon!", name_fr = "Gammerita, l'ami !", level = 48, requiredLevel = 44, raceMask = 8589934770,
            objective = "Katoom the Angler at Revantusk Village in the Hinterlands wants you to kill Gammerita and retrieve Katoom's Best Lure from her corpse.  Katoom mentioned that Gammerita hangs out on the coast with the other turtles.", objective_fr = "Katoom le pêcheur, du village des Revantusk dans les Hinterlands, veut que vous tuiez Gammerita et que vous récupériez le Meilleur appât de Katoom sur son cadavre.  Katoom a mentionné que Gammerita rôdait sur la côte, avec d’autres tortues.",
            start = { kind = "npc", id = 14740, name = "Katoom the Angler", name_fr = "Katoom le pêcheur", areaID = 47, uiMapID = 1425, x = 80.33, y = 81.54 },
            prerequisitesAny = { { id = 7815, name = "Snapjaws, Mon!", name_fr = "Les Gueules d'acier, l'ami !" } },
        },
        [7829] = {
            id = 7829, name = "Hunt the Savages", name_fr = "Chasser les sauvages", level = 48, requiredLevel = 44, raceMask = 8589934770,
            objective = "Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill 20 Savage Owlbeasts. Return to him once the task is complete.  Markhor mentioned that the Savage Owlbeasts occupy the wilds of the Hinterlands.", objective_fr = "Le veneur Markhor du village des Revantusk des Hinterlands veut que vous tuiez 20 Chouettards sauvages. Retournez le voir lorsque vous aurez terminé.  Markhor a mentionné que les Chouettards sauvages vivaient dans les régions sauvages des Hinterlands.",
            start = { kind = "npc", id = 14741, name = "Huntsman Markhor", name_fr = "Veneur Markhor", areaID = 47, uiMapID = 1425, x = 79.16, y = 79.53 },
        },
        [7841] = {
            id = 7841, name = "Message to the Wildhammer", name_fr = "Un message pour les Wildhammer", level = 48, requiredLevel = 44, raceMask = 8589934770,
            objective = "Otho Moji'ko at Revantusk Village in the Hinterlands wants you to slaughter 15 Highvale Outrunners, 15 Highvale Scouts, 15 Highvale Marksman and 15 Highvale Rangers. Return to him when this task is complete.  You can find the Highvale high elves at the Quel'Danil Lodge in the northwestern region of the Hinterlands.", objective_fr = "Otho Moji'ko du village des Revantusk dans les Hinterlands veut que vous massacriez 15 Estafettes du Haut-val, 15 Eclaireurs du Haut-val, 15 Tireurs d'élite du Haut-val et 15 Forestiers du Haut-val. Revenez le voir lorsque vous aurez terminé.  Vous pouvez trouver les elfes du Haut-val au Gîte de Quel’Danil, au nord-ouest des Hinterlands.",
            start = { kind = "npc", id = 14738, name = "Otho Moji'ko", name_fr = "Otho Moji'ko", areaID = 47, uiMapID = 1425, x = 79.38, y = 79.08 },
            nextQuest = { id = 7842, name = "Another Message to the Wildhammer", name_fr = "Encore un message pour les Wildhammer" },
        },
        [836] = {
            id = 836, name = "Rescue OOX-09/HL!", name_fr = "À la rescousse de OOX-09/HL !", level = 48, requiredLevel = 43, special = true,
            objective = "Escort OOX-09/HL to the shoreline beyond Overlook Cliff, then report to Oglethorpe Obnoticus in Booty Bay.", objective_fr = "Escorter OOX-09/HL jusqu'au littoral au-delà des Haut-Surplombs, puis rendre compte à Oglethorpe Obnoticus à Baie-du-Butin.",
            start = { kind = "npc", id = 7806, name = "Homing Robot OOX-09/HL", name_fr = "Robot guidé OOX-09/HL", areaID = 47, uiMapID = 1425, x = 49.35, y = 37.66 },
            prerequisitesAny = { { id = 485, name = "Find OOX-09/HL!", name_fr = "Trouver OOX-09/HL !" } },
        },
        [2877] = {
            id = 2877, name = "Skulk Rock Clean-up", name_fr = "Nettoyer le rocher de l'Affût", level = 48, requiredLevel = 40, raceMask = 4294967373,
            objective = "Kill 10 Green Sludges and 10 Jade Oozes, and then report back to Fraggar Thundermantle in Aerie Peak.", objective_fr = "Tuer 10 Limaces vertes et 10 Limons de jade puis faire votre rapport à Fraggar Thundermantle au Nid-de-l'Aigle",
            start = { kind = "npc", id = 7884, name = "Fraggar Thundermantle", name_fr = "Fraggar Thundermantle", areaID = 47, uiMapID = 1425, x = 14.83, y = 44.57 },
        },
        [7828] = {
            id = 7828, name = "Stalking the Stalkers", name_fr = "Traquer les traqueurs", level = 48, requiredLevel = 44, raceMask = 8589934770,
            objective = "Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill 10 Silvermane Stalkers and 10 Silvermane Howlers. Return to him once the task is complete.  Markhor mentioned that the wolves hide in the wilds of the Hinterlands.", objective_fr = "Le veneur Markhor du village des Revantusk, dans les Hinterlands, veut que vous tuiez 15 Traqueurs Crins-d'argent et 15 Hurleurs Crins-d'argent. Retournez le voir lorsque vous aurez terminé.  D’après Makhor, les loups se cachent dans les régions sauvages des Hinterlands.",
            start = { kind = "npc", id = 14741, name = "Huntsman Markhor", name_fr = "Veneur Markhor", areaID = 47, uiMapID = 1425, x = 79.16, y = 79.53 },
        },
        [2989] = {
            id = 2989, name = "The Altar of Zul", name_fr = "L'autel de Zul", level = 48, requiredLevel = 40, raceMask = 4294967373, special = true,
            objective = "Check the top of the Altar of Zul, then return to Gryphon Master Talonaxe.", objective_fr = "Regarder sur le dessus de l'autel de Zul, puis retourner auprès du Maître des gryphons Talonaxe.",
            start = { kind = "npc", id = 5636, name = "Gryphon Master Talonaxe", name_fr = "Maître des gryphons Talonaxe", areaID = 47, uiMapID = 1425, x = 9.75, y = 44.47 },
            prerequisitesAny = { { id = 2988, name = "Witherbark Cages", name_fr = "Les cages Witherbark" } },
            nextQuest = { id = 2990, name = "Thadius Grimshade", name_fr = "Thadius Grimshade" },
        },
        [7839] = {
            id = 7839, name = "Vilebranch Hooligans", name_fr = "Les voyous Vilebranch", level = 48, requiredLevel = 44, raceMask = 8589934770,
            objective = "Smith Slagtree at Revantusk Village in the Hinterlands wants you to find Slagtree's Lost Tools. Return to him once this task is complete.  You recall Smith Slagtree mentioning that the tools might be at one of the Vilebranch temples in the northeastern region of the Hinterlands. You should also check Skulk Rock.", objective_fr = "Le forgeron Slagtree du village des Revantusk, dans les Hinterlands, vous demande de retrouver les Outils perdus de Slagtree. Retournez le voir lorsque vous les aurez.  Il a laissé entendre qu’ils pourraient se trouver dans l’un des temples des Vilebranch, au nord-est des Hinterlands. Vous devriez aussi jeter un coup d’œil au rocher de l’Affût.",
            start = { kind = "npc", id = 14737, name = "Smith Slagtree", name_fr = "Forgeron Slagtree", areaID = 47, uiMapID = 1425, x = 77.23, y = 80.13 },
        },
        [7840] = {
            id = 7840, name = "Lard Lost His Lunch", name_fr = "Lard a perdu son déjeuner !", level = 49, requiredLevel = 44, raceMask = 8589934770,
            objective = "Lard at Revantusk Village in the Hinterlands wants you to find Lard's Lunch. Return to him when this task is complete.  Lard mentioned that he left it on the island to the north. Watch out for Vilebranch trolls.", objective_fr = "Lard, du village des Revantusk, dans les Hinterlands, veut que vous retrouviez le Repas de Lard. Retournez le voir lorsque ce sera fait.  D’après Lard, il l’aurait laissé dans l’île, au nord. Prenez garde aux trolls Vilebranch !",
            start = { kind = "npc", id = 14731, name = "Lard", name_fr = "Lard", areaID = 47, uiMapID = 1425, x = 78.14, y = 81.38 },
        },
        [7850] = {
            id = 7850, name = "Dark Vessels", name_fr = "Les calices ténébreux", level = 50, requiredLevel = 46, raceMask = 8589934770,
            objective = "Primal Torntusk at Revantusk Village in the Hinterlands wants you to recover 10 Vessels of Tainted Blood from Jintha'alor. Return to Primal Torntusk when this task is complete.", objective_fr = "L’Aînée Torntusk du village des Revantusk, dans les Hinterlands, veut que vous récupériez 10 Calices de sang corrompu à Jintha’alor. Retournez voir l’Aînée Torntusk lorsque vous aurez terminé.",
            start = { kind = "npc", id = 14736, name = "Primal Torntusk", name_fr = "L'Aînée Torntusk", areaID = 47, uiMapID = 1425, x = 78.2, y = 81.18 },
        },
        [7849] = {
            id = 7849, name = "Separation Anxiety", name_fr = "L’angoisse de la séparation", level = 50, requiredLevel = 46, raceMask = 8589934770,
            objective = "Huntsman Markhor at Revantusk Village in the Hinterlands wants you to recover his twin brother's remains. Find and return Huntsman Malkhor's Skull and Huntsman Malkhor's Bones to Huntsman Markhor.  Markhor mentioned that his brother's remains were fed to the oozes and wolves of the Vilebranch. He also mentioned that there is a refuse pit filled with oozes in Jintha'alor as well as a wolf den. Both of these places are near the top of the temple.", objective_fr = "Le veneur Markhor du village des Revantusk, dans les Hinterlands, veut que vous récupériez les restes de son frère jumeau. Trouvez le Crâne du veneur Malkhor et les Os du veneur Malkhor, et ramenez-les au veneur Markhor.  Markhor vous a dit que les restes de son frère avaient été abandonnés aux limons et aux loups des Vilebranch. Il a également mentionné l’existence d’une décharge remplie de limons à Jintha’alor, ainsi que celle d’un enclos à loups. Tous deux se trouvent près du sommet du temple.",
            start = { kind = "npc", id = 14741, name = "Huntsman Markhor", name_fr = "Veneur Markhor", areaID = 47, uiMapID = 1425, x = 79.16, y = 79.53 },
        },
        [7815] = {
            id = 7815, name = "Snapjaws, Mon!", name_fr = "Les Gueules d'acier, l'ami !", level = 50, requiredLevel = 44, raceMask = 8589934770,
            objective = "Katoom the Angler at Revantusk Village in the Hinterlands wants you to kill 15 Saltwater Snapjaw turtles. Return to him when you have completed this task.", objective_fr = "Katoom le pêcheur, du village des Revantusk des Hinterlands, veut que vous tuiez 15 tortues Gueules d’acier des mers. Retournez le voir lorsque vous aurez terminé.",
            start = { kind = "npc", id = 14740, name = "Katoom the Angler", name_fr = "Katoom le pêcheur", areaID = 47, uiMapID = 1425, x = 80.33, y = 81.54 },
        },
        [4787] = {
            id = 4787, name = "The Ancient Egg", name_fr = "L'oeuf antique", level = 50, requiredLevel = 40,
            objective = "Bring the Ancient Egg to Yeh'kinya in Tanaris.", objective_fr = "Apporter l'Oeuf antique à Yeh'kinya à Tanaris.",
            start = { kind = "npc", id = 8579, name = "Yeh'kinya", name_fr = "Yeh'kinya", areaID = 440, uiMapID = 1446, x = 66.99, y = 22.36 },
            prerequisitesAny = { { id = 3527, name = "The Prophecy of Mosh'aru", name_fr = "La prophétie de Mosh'aru" } },
            nextQuest = { id = 3528, name = "The God Hakkar", name_fr = "Le dieu Hakkar" },
        },
        [7843] = {
            id = 7843, name = "The Final Message to the Wildhammer", name_fr = "Le message final pour les Wildhammer", level = 50, requiredLevel = 44, raceMask = 8589934770, special = true,
            objective = "Otho Moji'ko at Revantusk Village in the Hinterlands wants you to travel to Aerie Peak in the western region of the Hinterlands and place the Final Message to the Wildhammer by the well in the center of town. Return to him once this task is complete.  Beware of angry Wildhammer dwarves and unruly members of the Alliance.", objective_fr = "Otho Moji'ko, du village des Revantusk dans les Hinterlands, vous demande de vous rendre au Nid-de-l’Aigle, à l’ouest des Hinterlands. Vous devez placer le Message final pour les Wildhammer près du puits, au cœur de la ville. Retournez le voir lorsque vous aurez accompli votre tâche.  Faites attention aux nains Wildhammer, qui risquent de mal le prendre, et aux autres membres de l’Alliance.",
            start = { kind = "npc", id = 14738, name = "Otho Moji'ko", name_fr = "Otho Moji'ko", areaID = 47, uiMapID = 1425, x = 79.38, y = 79.08 },
            prerequisitesAny = { { id = 7842, name = "Another Message to the Wildhammer", name_fr = "Encore un message pour les Wildhammer" } },
        },
        [7862] = {
            id = 7862, name = "Job Opening: Guard Captain of Revantusk Village", name_fr = "Offre d’emploi : capitaine de la garde du village des Revantusk", level = 51, requiredLevel = 46, raceMask = 8589934770,
            objective = "You have been tasked with the decimation of 20 Vilebranch Berserkers, 20 Vilebranch Shadow Hunters, 20 Vilebranch Blood Drinkers, and 20 Vilebranch Soul Eaters.  Should you complete this task, return to Primal Torntusk at Revantusk Village in the Hinterlands.", objective_fr = "Vous avez été <chargé/chargée> de liquider 20 Berserkers Vilebranch, 20 Chasseurs des ombres Vilebranch, 20 Sanguinaires Vilebranch et 20 Mangeurs d’âmes Vilebranch.  Lorsque vous aurez terminé, allez parler à l’Aînée Torntusk, du village de Revantusk dans les Hinterlands.",
            start = { kind = "object", id = 179913, name = "Call to Arms!", name_fr = "Aux armes !", areaID = 47, uiMapID = 1425, x = 79.08, y = 78.99 },
        },
        [7845] = {
            id = 7845, name = "Kidnapped Elder Torntusk!", name_fr = "L’Ancien Torntusk a été enlevé !", level = 51, requiredLevel = 46, raceMask = 8589934770,
            objective = "Primal Torntusk at Revantusk Village in the Hinterlands wants you to rescue her mate, Elder Torntusk, from Jintha'alor.  You have been told that he is being held prisoner atop Jintha'alor, the Vilebranch capital city located in the southern region of the Hinterlands.", objective_fr = "L’Aînée Torntusk du village des Raventusk des Hinterlands vous demande de libérer son compagnon, l’Ancien Torntusk, de Jintha’alor.  Vous savez qu’il est prisonnier au sommet de Jintha’alor, la capitale des Vilebranch, qui se trouve au sud des Hinterlands.",
            start = { kind = "npc", id = 14736, name = "Primal Torntusk", name_fr = "L'Aînée Torntusk", areaID = 47, uiMapID = 1425, x = 78.2, y = 81.18 },
            nextQuest = { id = 7846, name = "Recover the Key!", name_fr = "Récupérez la clé !" },
        },
        [7846] = {
            id = 7846, name = "Recover the Key!", name_fr = "Récupérez la clé !", level = 51, requiredLevel = 46, raceMask = 8589934770,
            objective = "Elder Torntusk at Jintha'alor wants you to kill Hitah'ya the Keeper to get the Shackle Key to his bindings. Return to Elder Torntusk when you have recovered the key.", objective_fr = "L’Ancien Torntusk, à Jintha’alor, veut que vous tuiez Hitah’ya la Gardienne afin de récupérer la Clé des menottes qui le retiennent. Lorsque vous aurez cette clé, retournez voir l’Ancien Torntusk.",
            start = { kind = "npc", id = 14757, name = "Elder Torntusk", name_fr = "L'Ancien Torntusk", areaID = 47, uiMapID = 1425, x = 59.69, y = 77.84 },
            prerequisitesAny = { { id = 7845, name = "Kidnapped Elder Torntusk!", name_fr = "L’Ancien Torntusk a été enlevé !" } },
            nextQuest = { id = 7847, name = "Return to Primal Torntusk", name_fr = "Retourner voir l’Aînée Torntusk" },
        },
        [7847] = {
            id = 7847, name = "Return to Primal Torntusk", name_fr = "Retourner voir l’Aînée Torntusk", level = 51, requiredLevel = 46, raceMask = 8589934770,
            objective = "Elder Torntusk at Jintha'alor wants you to return to Primal Torntusk at Revantusk Village with news of his rescue.", objective_fr = "L’Ancien Torntusk, à Jintha’alor, veut que vous retourniez voir l’Aînée Torntusk du village des Revantusk et que vous lui appreniez qu’il est sauvé.",
            start = { kind = "npc", id = 14757, name = "Elder Torntusk", name_fr = "L'Ancien Torntusk", areaID = 47, uiMapID = 1425, x = 59.69, y = 77.84 },
            prerequisitesAny = { { id = 7846, name = "Recover the Key!", name_fr = "Récupérez la clé !" } },
        },
        [7861] = {
            id = 7861, name = "Wanted: Vile Priestess Hexx and Her Minions", name_fr = "On recherche : la vile prêtresse Maléficia et ses sbires", level = 51, requiredLevel = 46, raceMask = 8589934770,
            objective = "You have been ordered to slay Vile Priestess Hexx and 20 Vilebranch Aman'zasi Guards. See Primal Torntusk at Revantusk Village in the Hinterlands once this task is complete.  Vile Priestess Hexx and the Aman'zasi Guards can be found atop Jintha'alor in the Hinterlands.", objective_fr = "Vous avez reçu l’ordre de tuer la vile prêtresse Maléficia et 20 Gardes Ama’zasi Vilebranch. Lorsque vous aurez terminé, allez voir l’Aînée Torntusk au village des Revantusk, dans les Hinterlands.  La vile prêtresse Maléficia et la garde Aman’zasi ont leurs quartiers au sommet de Jintha’alor, dans les Hinterlands.",
            start = { kind = "object", id = 179913, name = "Call to Arms!", name_fr = "Aux armes !", areaID = 47, uiMapID = 1425, x = 79.08, y = 78.99 },
        },
        [1446] = {
            id = 1446, name = "Jammal'an the Prophet", name_fr = "Jammal'an le Prophète", level = 53, requiredLevel = 38,
            objective = "The Atal'ai Exile in The Hinterlands wants the Head of Jammal'an.", objective_fr = "L'Exilé atal'ai des Hinterlands veut la Tête de Jammal'an.",
            start = { kind = "npc", id = 5598, name = "Atal'ai Exile", name_fr = "Exilé atal'ai", areaID = 47, uiMapID = 1425, x = 33.75, y = 75.21 },
        },
        [2994] = {
            id = 2994, name = "Saving Sharpbeak", name_fr = "Sauver Bec-tranchant", level = 53, requiredLevel = 40, raceMask = 4294967373,
            objective = "Fight to the top of Jintha'Alor, kill Vile Priestess Hexx for the key to Sharpbeak's cage, and save Sharpbeak.", objective_fr = "Combattre jusqu’au sommet de Jintha'Alor, tuer la vile prêtresse Maléficia pour obtenir la clé de la cage de Bec-tranchant, et sauver Bec-tranchant.",
            start = { kind = "npc", id = 5636, name = "Gryphon Master Talonaxe", name_fr = "Maître des gryphons Talonaxe", areaID = 47, uiMapID = 1425, x = 9.75, y = 44.47 },
            prerequisitesAny = { { id = 2993, name = "Return to the Hinterlands", name_fr = "Retour dans les Hinterlands" } },
        },
        [2937] = {
            id = 2937, name = "Summoning Shadra", name_fr = "L'invocation de Shadra", level = 55, requiredLevel = 40, raceMask = 8589934770,
            objective = "Defeat Shadra at the altar of Shadra'Alor, then bring her venom to Apothecary Lydon in Tarren Mill.", objective_fr = "Terrasser Shadra, à l'autel de Shadra'Alor, puis rapporter son venin à l'Apothicaire Lydon, au Moulin-de-Tarren.",
            start = { kind = "npc", id = 3188, name = "Master Gadrin", name_fr = "Maître Gadrin", areaID = 14, uiMapID = 1411, x = 55.95, y = 74.72 },
            prerequisitesAny = { { id = 2936, name = "The Spider God", name_fr = "Le dieu-araignée" } },
        },
        [2938] = {
            id = 2938, name = "Venom to the Undercity", name_fr = "Du venin pour Undercity", level = 55, requiredLevel = 40, raceMask = 8589934770,
            objective = "Bring Faranell's Parcel to Master Apothecary Faranell in the Undercity.", objective_fr = "Apporter le Colis de Faranell au maître apothicaire Faranell, à Undercity.",
            start = { kind = "npc", id = 2216, name = "Apothecary Lydon", name_fr = "Apothicaire Lydon", areaID = 267, uiMapID = 1424, x = 61.44, y = 19.06 },
            prerequisitesAny = { { id = 2937, name = "Summoning Shadra", name_fr = "L'invocation de Shadra" } },
        },
        [8643] = {
            id = 8643, name = "Highpeak the Elder", name_fr = "L'Ancien Highpeak", level = 60, requiredLevel = 1,
            start = { kind = "npc", id = 15559, name = "Elder Highpeak", name_fr = "Ancien Highpeak", areaID = 47, uiMapID = 1425, x = 50, y = 48.05 },
