        [7728] = {
            id = 7728, name = "STOLEN: Smithing Tuyere and Lookout's Spyglass", name_fr = "OBJETS VOLES : Tuyère et longue-vue", level = 48, requiredLevel = 45,
            objective = "Find and return the Smithing Tuyere and Lookout's Spyglass to Taskmaster Scrange in the Searing Gorge.  The only information you have about these items is the following: They were definitely stolen by Dark Iron dwarves. The Smithing Tuyere is a blacksmithing tool used by blacksmiths and the Lookout's Spyglass is an invaluable monitoring tool to lookouts.", objective_fr = "Trouvez la Tuyère de forge et la Longue-vue du guetteur et rapportez-les au sous-chef Scrange dans la gorge des Vents brûlants.  Les seules informations dont vous disposez sur ces objets sont les suivantes : ils ont été dérobés par les nains Sombrefer, la Tuyère de forge est un outil utilisé par les forgerons et la Longue-vue du guetteur est un outil de surveillance inestimable pour les guetteurs.",
            start = { kind = "object", id = 179827, name = "Wanted/Missing/Lost & Found", name_fr = "On recherche/Disparu/Trouvé & Perdu", areaID = 51, uiMapID = 1427, x = 37.65, y = 26.47 },
