            objective = "Hansel Heavyhands wants you to kill 20 Heavy War Golems.  The Heavy War Golems wander the areas surrounding the Cauldron in the Searing Gorge. When you've killed enough, return to Hansel in Searing Gorge.", objective_fr = "Hansel Heavyhands veut que vous tuiez 20 Golems de guerre lourds.  Les golems de guerre lourds errent dans les régions qui entourent le Chaudron dans la Gorge des Vents brûlants. Quand vous en aurez tué assez, revenez voir Hansel dans la Gorge des Vents brûlants.",
            start = { kind = "npc", id = 14627, name = "Hansel Heavyhands", name_fr = "Hansel Heavyhands", areaID = 51, uiMapID = 1427, x = 38.58, y = 27.81 },
        },
        [7724] = {
            id = 7724, name = "Fiery Menace!", name_fr = "Une menace incandescente", level = 49, requiredLevel = 45,
            objective = "Hansel Heavyhands wants you to kill 20 Greater Lava Spiders in the Searing Gorge. You can find Greater Lava Spiders in the plateaus and lava pools of the Searing Gorge.  Return to Hansel Heavyhands in the Searing Gorge when you have killed enough Greater Lava Spiders.", objective_fr = "Hansel Heavyhands veut que vous tuiez 20 Grandes araignées de lave dans la gorge des Vents brûlants. Vous pouvez trouver les Grandes araignées de lave dans les plateaux et les mares de lave de la gorge des Vents brûlants.  Revenez voir Hansel dans la gorge des Vents brûlants quand vous aurez tué assez de Grandes araignées de lave.",
            start = { kind = "npc", id = 14627, name = "Hansel Heavyhands", name_fr = "Hansel Heavyhands", areaID = 51, uiMapID = 1427, x = 38.58, y = 27.81 },
        },
        [7727] = {
            id = 7727, name = "Incendosaurs? Whateverosaur is More Like It", name_fr = "Incendosaures ? N'importosaures, plutôt", level = 49, requiredLevel = 45,
            objective = "Hansel Heavyhands wants you to kill 20 Incendosaurs.  You will find Incendosaurs occupying the lava pools inside the Slag Pit. The Slag Pit can be found in the Cauldron of the Searing Gorge.  Return to Hansel Heavyhands in the Searing Gorge when you have killed enough Incendosaurs.", objective_fr = "Hansel Heavyhands veut que vous tuiez 20 Incendosaures.  On peut les trouver dans les bassins de lave de la Fosse aux scories, qui occupe une partie du Chaudron de la gorge des Vents brûlants.  Retournez voir Hansel Heavyhands dans la gorge des Vents brûlants lorsque vous aurez tué suffisamment d’Incendosaures.",
            start = { kind = "npc", id = 14627, name = "Hansel Heavyhands", name_fr = "Hansel Heavyhands", areaID = 51, uiMapID = 1427, x = 38.58, y = 27.81 },
        },
