        [7701] = {
            id = 7701, name = "WANTED: Overseer Maltorius", name_fr = "ON RECHERCHE : Surveillant Maltorius", level = 50, requiredLevel = 45,
            objective = "Deep within the Slag Pit of the Cauldron, in the Searing Gorge, you will find the traitorous Dark Iron dwarf named Overseer Maltorius.  Slay Overseer Maltorius and take his head. Return the head to Lookout Captain Lolo Longstriker in the Searing Gorge for your reward.", objective_fr = "Loin dans les profondeurs de la Fosse aux scories dans le Chaudron, dans la Gorge des Vents brûlants, vous trouverez le nain traître du clan Sombrefer répondant au nom de surveillant Maltorius.  Tuez le surveillant Maltorius et prenez sa tête. Apportez-la au capitaine de guet Lolo Longstriker dans la Gorge des Vents brûlants pour la récompense.",
            start = { kind = "object", id = 179827, name = "Wanted/Missing/Lost & Found", name_fr = "On recherche/Disparu/Trouvé & Perdu", areaID = 51, uiMapID = 1427, x = 37.65, y = 26.47 },
        },
        [7722] = {
            id = 7722, name = "What the Flux?", name_fr = "Le Flux embrasé", level = 50, requiredLevel = 45,
            objective = "Somewhere in the Slag Pit of the Cauldron you will find the Secret Plans: Fiery Flux that Overseer Maltorius stole. Find those plans and return them to Master Smith Burninate in the Searing Gorge. ", objective_fr = "Quelque part dans la Fosse aux scories du Chaudron, vous trouverez les Plans secrets : Flux embrasé dérobés par le surveillant Maltorius. Trouvez ces plans et rapportez-les au Maître forgeron Burninate dans la gorge des Vents brûlants.",
            start = { kind = "npc", id = 14624, name = "Master Smith Burninate", name_fr = "Maître forgeron Burninate", areaID = 51, uiMapID = 1427, x = 38.8, y = 28.51 },
        },
        [3372] = {
            id = 3372, name = "Release Them", name_fr = "La libération", level = 52, requiredLevel = 40, raceMask = 4294967373,
            objective = "Find the Mysterious Artifact being guarded by the Twilight's Hammer Idolaters in the northwest quadrant of the Searing Gorge and bring it to the Altar of Suntara in the Slag Pit. ", objective_fr = "Trouver l'Artefact mystérieux gardé par le Marteau du crépuscule au nord.",
            start = { kind = "npc", id = 8417, name = "Dying Archaeologist", name_fr = "Archéologue mourant", areaID = 51, uiMapID = 1427, x = 41.14, y = 25.56 },
            prerequisitesAny = { { id = 3371, name = "Dwarven Justice", name_fr = "La justice des nains" } },
        },
        [3566] = {
