            objective = "Slay Lathoric the Black and Obsidion, and return to Thorius in Ironforge with the Head of Lathoric the Black and the Heart of Obsidion.", objective_fr = "Assassiner Lathoric le Noir et Obsidion, puis retourner voir Thorius, à Ironforge, avec la Tête de Lathoric le Noir et le Coeur d'Obsidion.",
            start = { kind = "npc", id = 8417, name = "Dying Archaeologist", name_fr = "Archéologue mourant", areaID = 51, uiMapID = 1427, x = 41.14, y = 25.56 },
