        },
        [3463] = {
            id = 3463, name = "Set Them Ablaze!", name_fr = "Allumer le feu !", level = 52, requiredLevel = 40,
            objective = "Set the North, South, East, and West Sentry Towers on fire by using the Torch of Retribution inside each of the buildings.  ", objective_fr = "Mettre le feu aux Tours de garde nord, sud, est, et ouest en utilisant la Torche de vindicte à l'intérieur de chaque tour.",
            start = { kind = "npc", id = 8509, name = "Squire Maltrake", name_fr = "Ecuyer Maltrake", areaID = 51, uiMapID = 1427, x = 39.17, y = 39 },
