        },
        [5144] = {
            id = 5144, name = "Elemental Leatherworking", name_fr = "Travail du cuir élémentaire", level = 55, requiredLevel = 40, raceMask = 4294967373,
            objective = "Bring 2 Heart of Fire, 2 Globe of Water, 2 Core of Earth, and 2 Breath of Wind to Sarah Tanner in Searing Gorge.  Completing this quest will give you access to the Elemental Leatherworking arts.  The completion of this quest will prevent you from learning Dragonscale Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so.", objective_fr = "Apporter 2 Coeurs de feu, 2 Globes d’eau, 2 Noyaux de terre, et 2 Souffles de vent à Sarah Tanner dans la Gorge des Vents brûlants.  L’accomplissement de cette quête donne accès aux arts du Travail du cuir élémentaire.  L’accomplissement de cette quête vous empêchera d’apprendre le Travail du cuir de dragon et le Travail du cuir tribal ; il faut être sûr du chemin que l’on veut suivre avant de faire ce choix.",
            start = { kind = "npc", id = 7868, name = "Sarah Tanner", name_fr = "Sarah Tanner", areaID = 51, uiMapID = 1427, x = 63.56, y = 75.97 },
        },
