        [5143] = {
            id = 5143, name = "Tribal Leatherworking", name_fr = "Travail du cuir tribal", level = 55, requiredLevel = 40, raceMask = 4294967373,
            objective = "Bring a Wild Leather Vest and a Wild Leather Helmet to Caryssia Moonhunter in Feralas.  Completing this quest will give you access to the Tribal Leatherworking arts.  The completion of this quest will prevent you from learning Dragonscale Leatherworking and Elemental Leatherworking; be sure this is the path you wish to follow before doing so.", objective_fr = "Apporter un Gilet en cuir sauvage et un Casque en cuir sauvage à Caryssia Moonhunter en Feralas.  L’accomplissement de cette quête donne accès aux arts du travail du cuir tribal.  L’accomplissement de cette quête vous empêchera d’apprendre le travail du cuir de dragon et le travail du cuir élémentaire ; il faut être sûr du chemin que l’on veut suivre avant de faire ce choix.",
            start = { kind = "npc", id = 7870, name = "Caryssia Moonhunter", name_fr = "Caryssia Moonhunter", areaID = 357, uiMapID = 1444, x = 89.42, y = 46.55 },
