        [7441] = {
            id = 7441, name = "Pusillin and the Elder Azj'Tordin", name_fr = "Pusillin et l'Ancien Azj'Tordin", level = 58, requiredLevel = 54,
            objective = "Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary.  Return to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations.", objective_fr = "Rendez-vous à Hache-tripes et trouvez le diablotin Pusillin. Persuadez-le par tous les moyens de vous rendre le Livre d’Incantations d’Azj’Tordin.  Si vous parvenez à le récupérer, retournez voir Azj’Tordin au Pavillon de Lariss, en Feralas.",
