            prerequisitesAny = { { id = 1171, name = "The Brood of Onyxia", name_fr = "La portée d'Onyxia" } },
        },
        [6624] = {
            id = 6624, name = "Triage", name_fr = "Triage", level = 45, requiredLevel = 35, raceMask = 4294967373, special = true,
            objective = "Save patients by using Triage Bandages to tend to their wounds. You must save 15 patients before 6 of them die from their injuries.  Remember the order of triage! Critically Injured Soldiers die the fastest followed by Badly Injured Soldiers. Injured Soldiers take the longest to die and should be saved AFTER your Critically Injured and Badly Injured Soldiers have been triaged.", objective_fr = "Sauver des patients en utilisant des Bandages de Triage, afin de panser leurs blessures. Vous devez sauver 15 patients avant que 6 d’entre eux ne meurent de leurs blessures.  Rappelez-vous l’ordre du triage ! Les Soldats agonisants meurent les premiers, suivis des Soldats grièvement blessés. Les Soldats blessés sont ceux qui meurent les derniers, et ils doivent être soignés APRES ceux qui agonisent et ceux qui sont grièvement blessés ; selon le tri que vous avez fait.",
            start = { kind = "npc", id = 12939, name = "Doctor Gustaf VanHowzen", name_fr = "Docteur Gustaf VanHowzen", areaID = 15, uiMapID = 1445, x = 67.76, y = 48.97 },
        },
        [2846] = {
            id = 2846, name = "Tiara of the Deep", name_fr = "La tiare des abysses", level = 46, requiredLevel = 40,
            objective = "Bring the Tiara of the Deep to Tabetha in Dustwallow Marsh.", objective_fr = "Rapporter la Tiare des abysses à Tabetha au marécage d'Âprefange.",
            start = { kind = "npc", id = 6546, name = "Tabetha", name_fr = "Tabetha", areaID = 15, uiMapID = 1445, x = 46.06, y = 57.09 },
        },
        [6601] = {
            id = 6601, name = "Ascension...", name_fr = "Ascension...", level = 60, requiredLevel = 55, raceMask = 8589934770,
            objective = "It would appear as if the charade is over. You know that the Amulet of Draconic Subversion that Myranda the Hag created for you will not function inside Blackrock Spire. Perhaps you should find Rexxar and explain your predicament. Show him the Dull Drakefire Amulet. Hopefully he will know what to do next.", objective_fr = "Il semble que la comédie soit finie. Vous savez que l’Amulette de subversion draconique, créée par Myranda la Mégère, ne fonctionnera pas à l’intérieur du pic Blackrock. Peut-être devriez-vous trouver Rexxar et lui exposer votre fâcheuse situation. Montrez-lui l'Amulette drakefeu terne. Avec un peu de chance, il saura quoi faire.",
            start = { kind = "npc", id = 10321, name = "Emberstrife", name_fr = "Brandeguerre", areaID = 15, uiMapID = 1445, x = 56.66, y = 87.72 },
            prerequisitesAny = { { id = 6585, name = "The Test of Skulls, Axtroz", name_fr = "L'épreuve des crânes, Axtroz" } },
            nextQuest = { id = 6602, name = "Blood of the Black Dragon Champion", name_fr = "Le sang du champion des dragons noirs" },
        },
        [6570] = {
            id = 6570, name = "Emberstrife", name_fr = "Brandeguerre", level = 60, requiredLevel = 55, raceMask = 8589934770,
            objective = "Travel to the Wyrmbog in Dustwallow Marsh and seek out Emberstrife's Den. Once inside, wear the Amulet of Draconic Subversion and speak with Emberstrife. ", objective_fr = "Aller à la tourbière du Ver, dans le marécage d'Âprefange, et chercher la tanière de Brandeguerre. Une fois à l’intérieur, porter l’Amulette de subversion draconique, et parler à Brandeguerre.",
            start = { kind = "npc", id = 11872, name = "Myranda the Hag", name_fr = "Myranda la Mégère", areaID = 28, uiMapID = 1422, x = 50.79, y = 77.85 },
            prerequisitesAny = { { id = 6569, name = "Oculus Illusions", name_fr = "Illusions d'Occulus" } },
        },
        [6585] = {
            id = 6585, name = "The Test of Skulls, Axtroz", name_fr = "L'épreuve des crânes, Axtroz", level = 60, requiredLevel = 55, raceMask = 8589934770,
            objective = "Travel to Grim Batol and track down Axtroz, drake champion of the Red Flight. Destroy him and take his skull. Return the skull to Emberstrife.", objective_fr = "Aller à Grim Batol et traquer Axtroz, le Champion drake du Vol rouge. Le tuer et arracher son crâne, puis l’apporter à Brandeguerre.",
            start = { kind = "npc", id = 10321, name = "Emberstrife", name_fr = "Brandeguerre", areaID = 15, uiMapID = 1445, x = 56.66, y = 87.72 },
            prerequisitesAll = { { id = 6582, name = "The Test of Skulls, Scryer", name_fr = "L'épreuve des crânes, Clairvoyant" }, { id = 6583, name = "The Test of Skulls, Somnus", name_fr = "L'épreuve des crânes, Somnus" }, { id = 6584, name = "The Test of Skulls, Chronalis", name_fr = "L'épreuve des crânes, Chronalis" } },
            nextQuest = { id = 6601, name = "Ascension...", name_fr = "Ascension..." },
        },
        [6584] = {
            id = 6584, name = "The Test of Skulls, Chronalis", name_fr = "L'épreuve des crânes, Chronalis", level = 60, requiredLevel = 55, raceMask = 8589934770,
            objective = "Guarding the Caverns of Time in the Tanaris Desert is Chronalis, child of Nozdormu. Destroy him and return his skull to Emberstrife.", objective_fr = "Chronalis, enfant de Nozdormu, garde les Grottes du temps, dans le Désert de Tanaris. Tuez-le et rapportez son crâne à Brandeguerre.",
            start = { kind = "npc", id = 10321, name = "Emberstrife", name_fr = "Brandeguerre", areaID = 15, uiMapID = 1445, x = 56.66, y = 87.72 },
            prerequisitesAny = { { id = 6570, name = "Emberstrife", name_fr = "Brandeguerre" } },
        },
        [6582] = {
            id = 6582, name = "The Test of Skulls, Scryer", name_fr = "L'épreuve des crânes, Clairvoyant", level = 60, requiredLevel = 55, raceMask = 8589934770,
            objective = "You must find the blue dragonflight drake champion, Scryer, and slay him. Pry his skull from his corpse and return it to Emberstrife.  You know that Scryer can be found in Winterspring.", objective_fr = "Vous devez trouver Clairvoyant, le drake champion du Vol bleu, et le tuer. Arracher son crâne à son cadavre, et le rapporter à Brandeguerre.  Clairvoyant se trouve au Berceau-de-l'Hiver.",
            start = { kind = "npc", id = 10321, name = "Emberstrife", name_fr = "Brandeguerre", areaID = 15, uiMapID = 1445, x = 56.66, y = 87.72 },
            prerequisitesAny = { { id = 6570, name = "Emberstrife", name_fr = "Brandeguerre" } },
        },
        [6583] = {
            id = 6583, name = "The Test of Skulls, Somnus", name_fr = "L'épreuve des crânes, Somnus", level = 60, requiredLevel = 55, raceMask = 8589934770,
            objective = "Destroy the drake champion of the Green Flight, Somnus. Take his skull and return it to Emberstrife.", objective_fr = "Détruire le Champion drake du Vol vert, Somnus. Arracher son crâne à son cadavre, puis le rapporter à Brandeguerre.",
            start = { kind = "npc", id = 10321, name = "Emberstrife", name_fr = "Brandeguerre", areaID = 15, uiMapID = 1445, x = 56.66, y = 87.72 },
            prerequisitesAny = { { id = 6570, name = "Emberstrife", name_fr = "Brandeguerre" } },
        },
    },
}
