        [8461] = {
            id = 8461, name = "Deadwood of the North", name_fr = "Les Mort-bois du nord", level = 55, requiredLevel = 45,
            objective = "Nafien would like you to kill 6 Deadwood Den Watchers, 6 Deadwood Avengers, and 6 Deadwood Shamans. Return to him in northern Felwood near the entrance to Timbermaw Hold.", objective_fr = "Nafien veut que vous tuiez 6 Protecteurs Mort-bois, 6 Vengeurs Mort-bois et 6 Chamans Mort-bois. Ensuite, retournez le voir dans le nord de Gangrebois, près de l'entrée du repaire des Grumegueules.",
            start = { kind = "npc", id = 15395, name = "Nafien", name_fr = "Nafien", areaID = 361, uiMapID = 1448, x = 64.77, y = 8.13 },
        },
        [8470] = {
            id = 8470, name = "Deadwood Ritual Totem", name_fr = "Le totem rituel des Mort-bois", level = 55, requiredLevel = 45,
            objective = "Take the Deadwood Ritual Totem inside Timbermaw Hold and see if one of the furbolgs there will find a use for the item. The Timbermaw will not speak with you unless you are of Neutral reputation or greater with them.", objective_fr = "Amener le Totem rituel mort-bois à l’intérieur du repaire des Grumegueules et voir si l’un des furbolgs qui s’y trouvent est capable d’en faire quelque chose. Les Grumegueules ne vous adresseront pas la parole s’ils ne sont pas Neutres à votre égard, au minimum.",
            start = { kind = "item", id = 20741, name = "Deadwood Ritual Totem", name_fr = "Totem rituel mort-bois" },
        },
        [5165] = {
            id = 5165, name = "Dousing the Flames of Protection", name_fr = "En calmant les flammes de protection", level = 55, requiredLevel = 48,
            objective = "Using the Purified Moon Well Water, douse the flames of the four braziers of protection within Shadow Hold in Felwood, then return to Greta Mosshoof in the Emerald Sanctuary.", objective_fr = "Avec de l’Eau de Puits de lune purifiée, éteindre les flammes des quatre braseros de protection à l’intérieur du Fort des ombres dans Gangrebois.",
            start = { kind = "npc", id = 10922, name = "Greta Mosshoof", name_fr = "Greta Mosshoof", areaID = 361, uiMapID = 1448, x = 51.21, y = 82.11 },
            prerequisitesAny = { { id = 5159, name = "Cleansed Water Returns to Felwood", name_fr = "L'eau purifiée retourne à Gangrebois" } },
        },
        [8466] = {
            id = 8466, name = "Feathers for Grazle", name_fr = "Des plumes pour Grifleur", level = 55, requiredLevel = 45, special = true,
            objective = "Some of the Deadwood furbolgs wear a distinctive headdress that may be used as a means of proof in thinning their numbers. Bring me a feather from any headdresses you acquire; for every set of five you bring me, you will earn recognition amongst the Timbermaw.", objective_fr = "Some of the Deadwood furbolgs wear a distinctive headdress that may be used as a means of proof in thinning their numbers. Bring me a feather from any headdresses you acquire; for every set of five you bring me, you will earn recognition amongst the Timbermaw.",
            start = { kind = "npc", id = 11554, name = "Grazle", name_fr = "Grifleur", areaID = 361, uiMapID = 1448, x = 50.93, y = 85.01 },
            prerequisitesAny = { { id = 8460, name = "Timbermaw Ally", name_fr = "Allié des Grumegueules" } },
        },
        [8467] = {
            id = 8467, name = "Feathers for Nafien", name_fr = "Des plumes pour Nafien", level = 55, requiredLevel = 45, special = true,
            objective = "Some of the Deadwood furbolgs wear a distinctive headdress that may be used as a means of proof in thinning their numbers. Bring me a feather from any headdresses you acquire; for every set of five you bring me, you will earn recognition amongst the Timbermaw.", objective_fr = "Some of the Deadwood furbolgs wear a distinctive headdress that may be used as a means of proof in thinning their numbers. Bring me a feather from any headdresses you acquire; for every set of five you bring me, you will earn recognition amongst the Timbermaw.",
            start = { kind = "npc", id = 15395, name = "Nafien", name_fr = "Nafien", areaID = 361, uiMapID = 1448, x = 64.77, y = 8.13 },
            prerequisitesAny = { { id = 8461, name = "Deadwood of the North", name_fr = "Les Mort-bois du nord" } },
        },
        [7602] = {
            id = 7602, name = "Flawless Fel Essence", name_fr = "La gangressence parfaite", level = 55, requiredLevel = 50, classMask = 256,
            objective = "Impsy in Felwood has asked that you bring him three Flawless Fel Essences originating from three distinct locations.  The Legashi Satyrs of Azshara hold the Flawless Fel Essence of their region. The Jaedenar Legionnaires of Jaedenar hold the Flawless Fel Essence of their region. The Felguard Sentries of the Blasted Lands hold the Flawless Fel Essence of their region.  Recover the Flawless Fel Essences and return to Impsy in Felwood.", objective_fr = "Démonet vous a demandé de lui apporter trois Gangressences parfaites, venant de trois régions distinctes.  Les satyres Legashi d'Azshara, les légionnaires de Jaedenar et les gangregardes sentinelles des Terres foudroyées détiennent la Gangressence parfaite de leur région.  Récupérez les Gangressences parfaites et rapportez-les à Démonet, à Gangrebois.",
            start = { kind = "npc", id = 14470, name = "Impsy", name_fr = "Démonet", areaID = 361, uiMapID = 1448, x = 41.36, y = 45.02 },
            prerequisitesAny = { { id = 7601, name = "What Niby Commands", name_fr = "Les Commandements de Niby" } },
            nextQuest = { id = 7603, name = "Kroshius' Infernal Core", name_fr = "Le noyau infernal de Kroshius" },
        },
        [7603] = {
            id = 7603, name = "Kroshius' Infernal Core", name_fr = "Le noyau infernal de Kroshius", level = 55, requiredLevel = 50, classMask = 256,
            objective = "Search Shatter Scar Vale in Felwood for the remains of Kroshius. When you locate the remains, use the Fel Fire near them and await Kroshius' return. When the infernal has awoken, slay him and take from his corpse Kroshius' Infernal Core.  Return Kroshius' Infernal Core to Niby the Almighty in Felwood.", objective_fr = "Fouillez le Val Grêlé pour trouver les restes de Kroshius. Quand vous les aurez localisés, utilisez le Gangrefeu à proximité et attendez le retour de Kroshius. Quand l'Infernal se sera réveillé, tuez-le et prenez le Noyau infernal sur son cadavre.  Rapportez le Noyau infernal de Kroshius à Niby le Tout-Puissant, à Gangrebois.",
            start = { kind = "npc", id = 14470, name = "Impsy", name_fr = "Démonet", areaID = 361, uiMapID = 1448, x = 41.36, y = 45.02 },
            prerequisitesAny = { { id = 7602, name = "Flawless Fel Essence", name_fr = "La gangressence parfaite" } },
        },
        [5203] = {
            id = 5203, name = "Rescue From Jaedenar", name_fr = "Sauvetage à Jaedenar", level = 55, requiredLevel = 49, special = true,
            objective = "Escort Arko'narin to where Lightforge and her equipment are being held, and then protect her as you escape Shadow Hold. Afterwards, seek out Jessir Moonbow in Felwood to let her know what's happened to her friends.", objective_fr = "Escorter Arko'narin à l’endroit où Lightforge et son équipement sont détenus, puis la protéger lors de l’évasion du Fort des ombres. Ensuite, aller trouver Jessir Moonbow dans Gangrebois pour lui apprendre ce qui est arrivé à ses amis.",
            start = { kind = "npc", id = 11016, name = "Captured Arko'narin", name_fr = "Arko'narin capturée", areaID = 361, uiMapID = 1448, x = 36.21, y = 55.47 },
            prerequisitesAny = { { id = 5202, name = "A Strange Red Key", name_fr = "Une étrange clé rouge" } },
            nextQuest = { id = 5204, name = "Retribution of the Light", name_fr = "Le châtiment de la Lumière" },
        },
        [6031] = {
            id = 6031, name = "Runecloth", name_fr = "L'étoffe runique", level = 55, requiredLevel = 50,
            objective = "Bring 30 Runecloth to Meilosh in Timbermaw Hold.", objective_fr = "Apportez 30 pièces d'étoffe runique à Meilosh au Repaire des Grumegueules.",
