        [4261] = {
            id = 4261, name = "Ancient Spirit", name_fr = "Esprit d'un ancien", level = 56, requiredLevel = 49, raceMask = 4294967373, special = true,
            objective = "Escort Arei to safety, then speak with Kayneth Stillwind in Forest Song, in eastern Ashenvale.", objective_fr = "Escorter Arei jusqu’à un lieu sûr, puis parler à Kayneth Stillwind au Chant des forêts, dans l’est d'Ashenvale.",
            start = { kind = "npc", id = 9598, name = "Arei", name_fr = "Arei" },
