        [8469] = {
            id = 8469, name = "Beads for Salfa", name_fr = "Des perles pour Salfa", level = 56, requiredLevel = 50, special = true,
            objective = "The Winterfall are known to carry spirit beads to ward against foul spirits. These beads have clearly failed in their purpose, as the Winterfall themselves are the agents of corruption. Bring to me these spirit beads from fallen Winterfall furbolgs; for every set of five you bring me, you will earn recognition amongst the Timbermaw.", objective_fr = "The Winterfall are known to carry spirit beads to ward against foul spirits. These beads have clearly failed in their purpose, as the Winterfall themselves are the agents of corruption. Bring to me these spirit beads from fallen Winterfall furbolgs; for every set of five you bring me, you will earn recognition amongst the Timbermaw.",
            start = { kind = "npc", id = 11556, name = "Salfa", name_fr = "Salfa", areaID = 618, uiMapID = 1452, x = 27.73, y = 34.5 },
            prerequisitesAny = { { id = 8464, name = "Winterfall Activity", name_fr = "Les Tombe-hiver s'agitent" } },
        },
        [5249] = {
            id = 5249, name = "To Winterspring!", name_fr = "Au Berceau-de-l'Hiver", level = 56, requiredLevel = 53, raceMask = 4294967373,
