        [8736] = {
            id = 8736, name = "The Nightmare Manifests", name_fr = "Le Cauchemar se manifeste", level = 60, requiredLevel = 60, special = true,
            objective = "Defend Nighthaven from Eranikus. Do not let Keeper Remulos perish. Do not slay Eranikus. Defend yourself. Await Tyrande. ", objective_fr = "Défendre Havrenuit d’Eranikus. Le Gardien Remulos ne doit pas mourir. Eranikus non plus. Défendez-vous. Attendez Tyrande.",
            start = { kind = "npc", id = 11832, name = "Keeper Remulos", name_fr = "Gardien Remulos", areaID = 493, uiMapID = 1450, x = 36.18, y = 41.79 },
