        [8735] = {
            id = 8735, name = "The Nightmare's Corruption", name_fr = "La corruption du Cauchemar", level = 60, requiredLevel = 60,
            objective = "Travel to the four Emerald Dream portals in Azeroth and collect a Fragment of the Nightmare's Corruption from each. Return to Keeper Remulos in the Moonglade when you have completed this task. ", objective_fr = "Rendez-vous aux quatre portails qui ouvrent sur le Rêve d’Emeraude et récupérez un Fragment de la corruption du Cauchemar auprès de chacun d’eux. Lorsque vous aurez terminé, retournez voir le Gardien Remulos à Reflet-de-Lune.",
