        [8507] = {
            id = 8507, name = "Field Duty", name_fr = "Votre affectation", level = 60, requiredLevel = 60, raceMask = 4294967373, special = true,
            objective = "Report for duty at the Ironforge Brigade post near Hive'Zora. Prepare your Unsigned Field Duty Papers and obtain Signed Field Duty Papers from Captain Blackanvil and return to Windcaller Kaldon at Cenarion Hold in Silithus.  Note: Healing or casting beneficial spells on a member of the Ironforge Brigade will flag you for PvP.", objective_fr = "Présentez-vous au poste de la brigade d’Ironforge devant la Ruche’Zora. Préparez votre Ordre de mission et obtenez un Ordre de mission signé du capitaine Blackanvil. Ensuite, retournez voir l'Implorateur céleste Kaldon au Fort cénarien, en Silithus.  Note : lancer un sort de soin, ou tout autre sort bénéfique, sur un membre de la brigade d’Ironforge vous infligera un marqueur JcJ.",
            start = { kind = "npc", id = 15540, name = "Windcaller Kaldon", name_fr = "Implorateur céleste Kaldon", areaID = 1377, uiMapID = 1451, x = 49.98, y = 36.35 },
        },
