        [8309] = {
            id = 8309, name = "Glyph Chasing", name_fr = "À la poursuite des glyphes", level = 60, requiredLevel = 58,
            objective = "Rutgar Glyphshaper at Bronzebeard's Encampment in Silithus wants you to venture to Hive'Ashi, Hive'Zora, and Hive'Regal and recover Glyphed Rubbings from the Glyphed Crystals of each hive.  Use the Geologist's Transcription Kit to make a reasonable facsimile of the ancient glyphs. Return to Rutgar Glyphshaper when you complete this task.", objective_fr = "Rutgar Glyphshaper, du campement de Bronzebeard en Silithus, veut que vous entriez dans Ruche’Ashi, Ruche’Zora et Ruche’Regal et que vous récupériez des reproductions des Cristaux ornés de glyphes dans chaque ruche.  Utilisez la Trousse de transcription du géologue pour obtenir une copie correcte de ces glyphes antiques. Lorsque vous aurez terminé, retournez voir Rutgar Glyphshaper.",
            start = { kind = "npc", id = 15170, name = "Rutgar Glyphshaper", name_fr = "Rutgar Glyphshaper", areaID = 1377, uiMapID = 1451, x = 41.28, y = 88.45 },
