        [8306] = {
            id = 8306, name = "Into The Maw of Madness", name_fr = "L'antre de la folie", level = 60, requiredLevel = 58,
            objective = "Commander Mar'alith at Cenarion Hold in Silithus wants you to find his beloved Natalia. The information that you gathered points to Hive'Regal in the south as being the area in which you may find Mistress Natalia Mar'alith.  Do not forget to visit the dwarves at Bronzebeard's camp before venturing into the hive. They might have some additional work and advice for you.  And $N, remember the Commander's words: \"Do what you must...\"", objective_fr = "Le commandant Mar'alith au Fort cénarien en Silithus veut que vous retrouviez sa bien-aimée, Natalia. Selon les informations que vous avez réunies, la Ruche'Regal au sud serait l'endroit où vous pourriez trouver dame Natalia Mar'alith.  N'oubliez pas de rendre visite aux nains au camp de Bronzebeard avant de vous aventurer dans la ruche. Ils ont peut-être d'autres tâches à vous confier et des conseils pour vous.  Et <nom>, souvenez-vous des mots du commandant : \"Faites votre devoir...\"",
            start = { kind = "npc", id = 15181, name = "Commander Mar'alith", name_fr = "Commandant Mar'alith", areaID = 1377, uiMapID = 1451, x = 49.2, y = 34.18 },
            prerequisitesAny = { { id = 8304, name = "Dearest Natalia", name_fr = "Chère Natalia" } },
