        [8315] = {
            id = 8315, name = "The Calling", name_fr = "L'appel", level = 60, requiredLevel = 58,
            objective = "Geologist Larksbane at Cenarion Hold in Silithus wants you to recover the Crystal Unlocking Mechanism from the Qiraji Emissary.  You have been instructed to take the Glyphs of Calling to the Bones of Grakkarond, south of Cenarion Hold, and draw them in the sand. Should the Qiraji Emissary appear, slay it and recover the Crystal Unlocking Mechanism. Return to Geologist Larksbane if you succeed.  Assemble an army for this task, $N!", objective_fr = "La géologue Larksbane, au Fort cénarien en Silithus, veut que vous récupériez le Mécanisme de déverrouillage du cristal sur le Maître des clés.  Elle vous a demandé de vous rendre près des Restes de Grakkarond, au sud du Fort cénarien, et d’y dessiner les glyphes d'appel dans le sable. Si le Maître des clés apparaît, tuez-le et récupérez le Mécanisme de déverrouillage du cristal. Ensuite, si vous avez réussi, retournez voir la géologue Larksbane.  Elle vous a conseillé d’emmener une armée, <nom>.",
            start = { kind = "npc", id = 15183, name = "Geologist Larksbane", name_fr = "Géologue Larksbane", areaID = 1377, uiMapID = 1451, x = 49.67, y = 37.46 },
            prerequisitesAny = { { id = 8314, name = "Unraveling the Mystery", name_fr = "Dévoiler le mystère" } },
        },
        [8538] = {
            id = 8538, name = "The Four Dukes", name_fr = "Les quatre ducs", level = 60, requiredLevel = 60, special = true,
            objective = "Find a way to summon and slay the Duke of Cynders, the Duke of Fathoms, the Duke of Zephyrs and the Duke of Shards and report back to Commander Mar'alith in Cenarion Hold. You must also bring Tactical Task Briefing V in order to complete this quest.", objective_fr = "Trouver un moyen d’invoquer et de tuer les duc des Cendres, le duc des Profondeurs, le duc des Zéphyrs et le duc des Éclats, puis revenir voir le commandant Mar'alith au Fort cénarien. Pour terminer cette quête, vous devez aussi apporter le Briefing tactique V.",
            start = { kind = "item", id = 20948, name = "Tactical Task Briefing V", name_fr = "Briefing tactique V" },
        },
