        [5127] = {
            id = 5127, name = "The Demon Forge", name_fr = "La forge démoniaque", level = 60, requiredLevel = 55,
            objective = "Travel to Blackrock Spire and find Goraluk Anvilcrack. Slay him and then use the Blood Stained Pike upon his corpse. After his soul has been siphoned, the pike will be Soul Stained.  You must also find the Unforged Rune Covered Breastplate.  Return both the Soul Stained Pike and the Unforged Rune Covered Breastplate to Lorax in Winterspring.", objective_fr = "Se rendre au pic Blackrock et trouver Goraluk Anvilcrack. Le tuer puis utiliser la Pique tachée de sang sur son cadavre. Après avoir siphonné son âme, la pique sera devenue Tachée d'âme.  Trouver aussi la Cuirasse couverte de runes inachevée.  Rapporter la Pique tachée d'âme et la Cuirasse couverte de runes inachevée à Lorax au Berceau-de-l'Hiver.",
            start = { kind = "npc", id = 10918, name = "Lorax", name_fr = "Lorax", areaID = 618, uiMapID = 1452, x = 63.79, y = 73.76 },
