        [7643] = {
            id = 7643, name = "Ancient Equine Spirit", name_fr = "L'ancien esprit équin", level = 60, requiredLevel = 60, raceMask = 5, classMask = 2,
            objective = "Acquire special horse feed used for feeding a spirit horse. Merideth Carlson in Southshore apparently is the source for such food.  Travel to the Dire Maul dungeon in Feralas and slay Tendris Warpwood. Doing so will free the Ancient Equine Spirit. Feed it the special horse feed, thereby soothing the spirit. Finally, give it the Arcanite Barding so it may bless it.", objective_fr = "Procurez-vous un aliment pour chevaux capable de nourrir un esprit équin. Il semble que Merideth Carlson, à Southshore, sache en fabriquer.  Ensuite, rendez-vous au donjon de Hache-tripes en Feralas, et tuez Tendris Crochebois. Sa mort libérera l’Ancien esprit équin. Nourrissez-le avec l’aliment spécial afin de l’apaiser. Enfin, donnez-lui le Caparaçon d’arcanite pour qu’il le bénisse.",
            start = { kind = "npc", id = 928, name = "Lord Grayson Shadowbreaker", name_fr = "Seigneur Grayson Shadowbreaker", areaID = 1519, uiMapID = 1453, x = 48.43, y = 50.22 },
