        [8746] = {
            id = 8746, name = "Metzen the Reindeer", name_fr = "Metzen le renne", level = 60, requiredLevel = 40, raceMask = 8589934770,
            objective = "Find Metzen the Reindeer. Use the notes provided to you for clues as to where he is being held.  When you find Metzen, have the Pouch of Reindeer Dust in your possession so you can sprinkle some of the dust on him; this should free Metzen from his bonds of captivity.  Return the Pouch of Reindeer Dust to Kaymard Copperpinch in Orgrimmar once Metzen is freed.", objective_fr = "Trouvez Metzen le renne. Utilisez les notes qui vous ont été fournies comme indices pour découvrir son lieu de détention.  Quand vous aurez trouvé Metzen, saupoudrez sur lui la Bourse de poudre de renne qui vous a été remise. Cela devrait mettre fin à sa captivité.  Rapportez la Bourse de poudre de renne à Kaymard Copperpinch à Orgrimmar quand Metzen aura été libéré.",
            start = { kind = "npc", id = 13418, name = "Kaymard Copperpinch", name_fr = "Kaymard Copperpinch", areaID = 1637, uiMapID = 1454, x = 53.33, y = 66.49 },
