        [8258] = {
            id = 8258, name = "The Darkreaver Menace", name_fr = "La menace de Ravassombre", level = 60, requiredLevel = 60, raceMask = 8589934770, classMask = 64,
            objective = "Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance. Doing so will bring forth spirits you must fight. Defeating these spirits will summon forth Death Knight Darkreaver; defeat him.  Bring Darkreaver's Head to Sagorne Creststrider in the Valley of Wisdom, Orgrimmar.", objective_fr = "Servez-vous du Clairvoyant au centre du sous-sol du Grand ossuaire de la Scholomance. Cela attirera des esprits que vous devrez combattre. Les vaincre fera apparaître le Chevalier de la mort Ravassombre. Tuez-le.  Rapportez la Tête de Ravassombre à Sagorne Rôdeur-des-crêtes de la Vallée de la Sagesse, à Orgrimmar.",
            start = { kind = "npc", id = 13417, name = "Sagorne Creststrider", name_fr = "Sagorne Creststrider", areaID = 1637, uiMapID = 1454, x = 38.66, y = 35.92 },
            prerequisitesAny = { { id = 7667, name = "Material Assistance", name_fr = "Assistance matérielle" } },
        },
        [7061] = {
            id = 7061, name = "The Feast of Winter Veil", name_fr = "La fête du Voile d'hiver", level = 60, requiredLevel = 10, raceMask = 8589934770,
            objective = "Feel free to read the book, \"The Feast of Winter Veil\", to learn more about the holiday. When you are finished with the book, deliver it to Cairne Bloodhoof in Thunder Bluff.", objective_fr = "Prenez le temps de lire ce livre, \"La fête du Voile d'hiver\", pour en apprendre plus sur cette période de fête. Quand vous en aurez fini avec le livre, apportez-le à Cairne Bloodhoof, dans la ville de Thunder Bluff.",
            start = { kind = "npc", id = 13417, name = "Sagorne Creststrider", name_fr = "Sagorne Creststrider", areaID = 1637, uiMapID = 1454, x = 38.66, y = 35.92 },
            prerequisitesAny = { { id = 6964, name = "The Reason for the Season", name_fr = "L'esprit de cette fête" } },
        },
