        [7001] = {
            id = 7001, name = "Empty Stables", name_fr = "Ecuries vides", level = 60, requiredLevel = 51, raceMask = 8589934770, special = true,
            objective = "Locate a Frostwolf in Alterac Valley. Use the Frostwolf Muzzle when you are near the Frostwolf to 'tame' the beast. Once tamed, the Frostwolf will follow you back to the Frostwolf Stable Master. Speak with the Frostwolf Stable Master to earn credit for the capture.", objective_fr = "Trouvez un Loup des glaces dans la vallée d’Alterac. Servez-vous de la Muselière de loup des glaces pour « dompter » la bête. Lorsque ce sera fait, le loup des glaces vous suivra jusqu’au Maître des écuries Frostwolf. Parlez au Maître des écuries Frostwolf pour être crédité de cette capture.",
            start = { kind = "npc", id = 13616, name = "Frostwolf Stable Master", name_fr = "Maître des écuries Frostwolf", areaID = 2597, uiMapID = 1459, x = 57.16, y = 82.45 },
        },
        [7027] = {
            id = 7027, name = "Empty Stables", name_fr = "Écuries vides", level = 60, requiredLevel = 51, raceMask = 4294967373, special = true,
            objective = "Locate an Alterac Ram in Alterac Valley. Use the Stormpike Training Collar when you are near the Alterac Ram to 'tame' the beast. Once tamed, the Alterac Ram will follow you back to the Stable Master. Speak with the Stable Master to earn credit for the capture. ", objective_fr = "Trouvez un Bélier d'Alterac dans la vallée d'Alterac. Lorsque vous serez à proximité, servez-vous du Collier d'entraînement Stormpike pour le \"dompter\". Une fois dompté, le Bélier d'Alterac vous suivra jusqu'au Maître des écuries. Parlez au Maître des écuries pour être crédité de cette capture.",
            start = { kind = "npc", id = 13617, name = "Stormpike Stable Master", name_fr = "Maître des écuries Stormpike", areaID = 2597, uiMapID = 1459, x = 42.55, y = 16.82 },
        },
