        [7241] = {
            id = 7241, name = "In Defense of Frostwolf", name_fr = "La défense des Frostwolf", level = 60, requiredLevel = 51, raceMask = 8589934770,
            objective = "Venture to Alterac Valley, located in the Alterac Mountains. Find and speak with Warmaster Laggrond - who stands outside the tunnel entrance - to begin your career as a soldier of Frostwolf. You will find Alterac Valley north of Tarren Mill at the base of the Alterac Mountains.", objective_fr = "Rendez-vous dans la vallée d'Alterac, dans les contreforts d'Hillsbrad. Trouvez le maître de guerre Laggrond, parlez-lui et commencez votre carrière comme soldat Frostwolf.",
            start = { kind = "npc", id = 13842, name = "Frostwolf Ambassador Rokhstrom", name_fr = "Ambassadrice Rokhstrom des Frostwolf", areaID = 1637, uiMapID = 1454, x = 49.61, y = 71.19 },
        },
