        [7202] = {
            id = 7202, name = "Korrak the Bloodrager", name_fr = "Korrak le Ragesang", level = 60, requiredLevel = 51, raceMask = 4294967373, special = true,
            objective = "According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley.  Should Korrak make himself known, destroy him and return to Lieutenant Haggerdin in the Alterac Mountains.", objective_fr = "Korrak le Ragesang se cache dans les profondeurs des cavernes Winterax. D’après la légende, le chef des puissants trolls Winterax ne se montre qu’après la mort de 500 de ses guerriers.  Rendez-vous aux cavernes Winterax et massacrez tout ce qui vous fait obstacle jusqu’à ce que Korrak se montre. Tuez-le et présentez-vous au Lieutenant Haggerdin.",
        },
        [7382] = {
            id = 7382, name = "Korrak the Everliving", name_fr = "Korrak l'Indestructible", level = 60, requiredLevel = 51, raceMask = 4294967373, special = true,
            objective = "Should Korrak the Bloodrager make a return to the Field of Strife, seek him out and destroy him.  Return the Skull of Korrak to Lieutenant Haggerdin in the Hillsbrad Foothills. ", objective_fr = "Si Korrak le Ragesang réapparaît dans le Champ sanglant, traquez-le et tuez-le.  Apportez le Crâne de Korrak au lieutenant Haggerdin dans les Contreforts de Hautebrande.",
        },
