        },
        [7363] = {
            id = 7363, name = "The Human Condition", name_fr = "La condition humaine", level = 60, requiredLevel = 51, raceMask = 8589934770, special = true,
            objective = "You have been tasked with slaying opposing human players in Alterac Valley.  Kill a human and return to Commander Louis Philips (who wanders between the front lines and Frostwolf keep) with a Human Bone Chip.  A cure for the human condition is close at hand!", objective_fr = "Vous avez été <chargé/chargée> de tuer les personnages humains présents dans la vallée d’Alterac.  Tuez un humain et présentez-vous au commandant Louis Philips (qui fait la navette entre le front et le donjon Loup-de-givre) avec un Bout d’os humain.  Un remède à la condition humaine est à portée de main !",
        },
        [7181] = {
            id = 7181, name = "The Legend of Korrak", name_fr = "La légende de Korrak", level = 60, requiredLevel = 51, raceMask = 8589934770, special = true,
            objective = "According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley.  Should Korrak make himself known, destroy him and return to Warmaster Laggrond.", objective_fr = "Korrak le Ragesang se cache dans les profondeurs des cavernes Winterax. D’après la légende, le chef des puissants trolls Winterax ne se montre qu’après la mort de 500 de ses guerriers.  Rendez-vous aux cavernes Winterax et massacrez tout ce qui vous fait obstacle jusqu’à ce que Korrak se montre. Tuez-le et présentez-vous au Maître de guerre Laggrond.",
        },
        [7121] = {
            id = 7121, name = "The Quartermaster", name_fr = "L'intendant", level = 60, requiredLevel = 51, raceMask = 4294967373,
            objective = "Speak with the Stormpike Quartermaster.", objective_fr = "Parlez à l’Intendant Stormpike.",
            start = { kind = "npc", id = 13797, name = "Mountaineer Boombellow", name_fr = "Montagnard Boombellow", areaID = 2597, uiMapID = 1459, x = 45.59, y = 16.71 },
        },
        [7381] = {
            id = 7381, name = "The Return of Korrak", name_fr = "Le retour de Korrak", level = 60, requiredLevel = 51, raceMask = 8589934770, special = true,
            objective = "Should Korrak the Bloodrager make a return to the Field of Strife, seek him out and destroy him.  Return the Skull of Korrak to Warmaster Laggrond in the Hillsbrad Foothills.", objective_fr = "Si Korrak le Ragesang devait réapparaître dans le Champ sanglant, traquez-le et tuez-le.  Apportez le Crâne de Korrak au Maître de guerre Laggrond dans les contreforts de Hautebrande.",
        },
        [7261] = {
            id = 7261, name = "The Sovereign Imperative", name_fr = "L'impératif souverain", level = 60, requiredLevel = 51, raceMask = 4294967373,
            objective = "Travel to Alterac Valley in the Hillsbrad Foothills. Outside of the entrance tunnel, find and speak with Lieutenant Haggerdin.  For the glory of Bronzebeard!", objective_fr = "Rendez-vous dans la vallée d'Alterac, dans les contreforts d'Hillsbrad. Présentez-vous au lieutenant Haggerdin.  Pour la gloire de Bronzebeard !",
            start = { kind = "npc", id = 13843, name = "Lieutenant Rotimer", name_fr = "Lieutenant Rotimer", areaID = 1537, uiMapID = 1455, x = 32.21, y = 63.26 },
        },
